# свой предмет: надзор облака с `system_admin` на кластере и вторым фактором кладёт
# посев церемонии (`seed_ceremony.py`), и LMR-01, LMR-03…05 несёт `kaname-access-keys`
# на собственном фронте службы. EV-14 несёт `kaname-address-verification` — на
# слушателе формы, тем же путём, что EV-11: отказ производит служба, копию текста
# края судит дом платформы.

# ДОВОД ОБ ОТСУТСТВИИ В ДЕРЕВЕ — УТВЕРЖДЕНИЕ О ДЕРЕВЕ, И СУДИТСЯ ОНО ДЕРЕВОМ
# (kaname#643). Двадцать семь записей Ф13 несли довод «полосы входа ключом в
# дереве нет» и после того, как полосу посадили (`internal/handler/loginlanehttp/
# handler.go`, пути `access-key/begin` и `access-key/login`): перепись читала
# довод как прозу, и он пережил свой предмет молча. Поэтому довод, утверждающий
# отсутствие (`ABSENCE_PHRASE_RE`), либо несёт ПРЕДИКАТ — запись `ABSENCE_CLAIMS`:
# метка в доводе, выражение предмета и каталоги, где его не должно быть, — и
# предикат исполняется на каждом прогоне, либо отвергается как непроверяемый.
# Совпадение предиката — находка «опровергнут деревом» с координатой первого
# совпадения. Каталоги, где не прочитано ни одного файла, — находка о слепоте:
# «ноль совпадений» на пустом обходе значил бы «ничего не прочитано». Запись
# предиката, которую не называет ни один довод, пережила свой довод и роняет
# перепись живого дерева. Сегодня отсутствие не утверждает ни один довод: был
# один — у Ф13-21, — и он снят вместе с предметом (kaname#669): причина конца
# сессии при снятии ключа посажена, кейс набора заведён, запись долга ушла.
ABSENCE_PHRASE_RE = re.compile(
    r"(?:в|на) дереве нет|нет (?:в|на) дереве|не называет ни один файл")
AbsenceClaims = dict[str, tuple[re.Pattern, re.Pattern, tuple[str, ...]]]
ABSENCE_CLAIMS: AbsenceClaims = {}


def _tree_hits(root: pathlib.Path, pattern: re.Pattern, dirs: tuple[str, ...]
               ) -> tuple[list[str], int]:
    """Совпадения предиката в каталогах дерева: координаты `путь:строка` и число
    прочитанных файлов."""
    hits: list[str] = []
    files = 0
    for d in dirs:
        base = root / d
        if not base.is_dir():
            continue
        for f in sorted(p for p in base.rglob("*") if p.is_file()):
            try:
                text = f.read_text(encoding="utf-8")
            except (UnicodeDecodeError, OSError):
                continue
            files += 1
            for n, line in enumerate(text.splitlines(), 1):
                if pattern.search(line):
                    hits.append(f"{f.relative_to(root).as_posix()}:{n}")
    return hits, files


def reconcile_absence_claims(root: pathlib.Path, reasons: dict[str, str],
                             claims: AbsenceClaims) -> tuple[list[str], dict[str, int]]:
    """Доводы ведомостей, утверждающие отсутствие в дереве, против самого дерева.

    `reasons` — «чья запись» → довод. Возвращает находки и перепись: доводов об
    отсутствии прочитано, из них с предикатом, файлов осмотрено, и какие
    предикаты названы доводами (`used`)."""
    out: list[str] = []
    census = {"claims": 0, "judged": 0, "files": 0}
    used: set[str] = set()
    for who, why in sorted(reasons.items()):
        matched = [name for name, (marker, _p, _d) in sorted(claims.items()) if marker.search(why)]
        if not matched and not ABSENCE_PHRASE_RE.search(why):
            continue
        census["claims"] += 1
        if not matched:
            out.append(f"довод {who} утверждает отсутствие в дереве, а предиката у него нет "
                       f"(`ABSENCE_CLAIMS`): проза об отсутствии не судится и переживает свой "
                       f"предмет молча — довод: {why[:160]!r}")
            continue
        census["judged"] += 1
        for name in matched:
            used.add(name)
            _marker, pattern, dirs = claims[name]
            hits, files = _tree_hits(root, pattern, dirs)
            census["files"] += files
            if files == 0:
                out.append(f"предикат довода {who} «{name}» беспредметен: осмотрено файлов 0 в "
                           f"{', '.join(dirs)} — «ноль совпадений» значил бы «ничего не прочитано»")
            elif hits:
                out.append(f"довод {who} опровергнут деревом: «{name}» — совпадений "
                           f"{len(hits)} в {', '.join(dirs)}, первое {hits[0]}")
    census["used"] = len(used)
    census["used_names"] = sorted(used)  # type: ignore[assignment]
    return out, census


def _surface_of_stem(stem, runnable, blocked) -> str:
    """Адресация позиции по её стеблю — для сверки двух величин между собой."""
    for s, surface, *_ in [*runnable, *blocked]:
        if s == stem:
            return surface
    return ""


Ledger = dict[str, tuple[str, str, str]]


def producer_of(stem: str, ledger: Ledger | None = None) -> tuple[str, str]:
    """Решение о производителе — ЧИТАЕТСЯ, а не выводится.

    Ведомость — ПАРАМЕТР, а не глобаль: самопроверка судит синтетические деревья,
    и подставить им объявленный перечень значило бы требовать записи о коллекциях,
    которых в дереве нет. Умолчание — объявленная ведомость.
    """
    cat, why, _holder = (PRODUCER_LEDGER if ledger is None else ledger)[stem]
    return cat, why


def holder_of(stem: str, ledger: Ledger | None = None) -> str:
    """Держатель позиции: задача, которая её прогонит. Пусто — держателя нет."""
    return (PRODUCER_LEDGER if ledger is None else ledger)[stem][2]


def reconcile_holders(stems: set[str], runs: dict[str, list[str]],
                      ledger: Ledger | None = None) -> list[str]:
    """Производитель в конвейере — шаг ЛИБО держатель, и сверка идёт В ОБЕ СТОРОНЫ.

    Негоняемая коллекция без держателя — долг без читателя: причина напечатана, а
    кто её снимет, не записано нигде. Держатель у коллекции, которую шаг уже
    гоняет, — запись, пережившая свой предмет: она обязана уйти тем же изменением,
    что завело шаг, иначе ведомость держателей стала бы ведомостью прощения.
    Позиция без записи ведомости здесь не судится — её называет
    `reconcile_producer_ledger`, и второй раз она не считается.
    """
    ledger = PRODUCER_LEDGER if ledger is None else ledger
    out = []
    for stem in sorted(stems & set(ledger)):
        holder = ledger[stem][2]
        where = runs.get(stem, [])
        if where and holder:
            out.append(f"держатель коллекции {stem} ({holder}) пережил предмет: её уже "
                       f"гоняет {'; '.join(where)} — запись снимается тем же изменением, "
                       f"что завело шаг")
        if not where and not holder:
            out.append(f"коллекция {stem} не гоняется ни одним шагом конвейера, а "
                       f"держателя в ведомости нет — кто снимет препятствие, не "
                       f"записано нигде")
        if holder and not HOLDER_RE.match(holder):
            out.append(f"держатель коллекции {stem} вне закрытой формы "
                       f"«PRO-Robotech/<репозиторий>#<номер> — <что сделает>»: {holder!r}")
    return out


# ─────────────── ПОЛОСЫ, НАЗВАННЫЕ ДЕРЖАТЕЛЕМ ───────────────────────────────
#
# Держатель вправе назвать полосы своей коллекции (`IBT-05`, `IBT-13`), и
# названная полоса — утверждение о МОДУЛЕ КЕЙСОВ: задача переутвердит то, что
# модуль несёт. Утверждение стареет вместе с модулем молча. Так и было: полосу
# IBT-12 сняли вместе с зеркалом набора ключей (kaname#361), модуль сказал это
# своей докстрокой, а держатель продолжал называть её полосой, которую задача
# переутвердит.
#
# Полоса модуля — приставка `<СЕМЕЙСТВО>-<номер>` у значения `id=` в вызове,
# которым модуль заводит кейс. Докстрока и комментарий полосы НЕ несут: снятая
# полоса в докстроке названа именно затем, чтобы сказать, что её нет.
# Судится только семейство, которое модуль сам ведёт: ссылка на полосу чужого
# семейства — не утверждение о модуле, и она печатается несудимой, а не
# прощается молча.
LANE_ID_RE = re.compile(r"^([A-Z][A-Z0-9]*)-([0-9]+)(?:-|$)")
LANE_REF_RE = re.compile(r"(?<![A-Za-z0-9-])([A-Z][A-Z0-9]*)-([0-9]+)(?![0-9A-Za-z])")


def module_case_ids(cases: pathlib.Path, stem: str) -> list[str] | None:
    """Значения `id=` вызовов модуля кейсов коллекции. None — модуля нет."""
    import ast as _ast
    mod = cases / f"{stem}.py"
    if not mod.is_file():
        return None
    tree = _ast.parse(mod.read_text(encoding="utf-8"), filename=str(mod))
    return [k.value.value for n in _ast.walk(tree) if isinstance(n, _ast.Call)
            for k in n.keywords
            if k.arg == "id" and isinstance(k.value, _ast.Constant)
            and isinstance(k.value.value, str)]


def reconcile_holder_lanes(cases: pathlib.Path, ledger: Ledger | None = None
                           ) -> tuple[list[str], dict[str, int]]:
    """Полоса, названная держателем, есть у модуля кейсов его коллекции.

    Возвращает находки и перепись: держателей прочитано, полос ими названо, из
    них судимо (семейство модуля). Модуль, не давший ни одного `id=`, при
    названной держателем полосе — находка: «полосы нет» тогда значило бы «кейсов
    не прочитано».
    """
    ledger = PRODUCER_LEDGER if ledger is None else ledger
    out: list[str] = []
    census = {"holders": 0, "named": 0, "judged": 0}
    for stem, (_cat, _why, holder) in sorted(ledger.items()):
        if not holder:
            continue
        census["holders"] += 1
        refs = [f"{fam}-{num}" for fam, num in LANE_REF_RE.findall(holder)]
        if not refs:
            continue
        census["named"] += len(refs)
        ids = module_case_ids(cases, stem)
        if ids is None:
            continue
        if not ids:
            out.append(f"держатель коллекции {stem} называет полосы ({', '.join(refs)}), а "
                       f"модуль кейсов {stem}.py не дал ни одного `id=` — судить их не по чему, "
                       f"и «полосы нет» значило бы «кейсов не прочитано»")
            continue
        lanes = {f"{m.group(1)}-{m.group(2)}" for m in map(LANE_ID_RE.match, ids) if m}
        families = {lane.split("-")[0] for lane in lanes}
        for ref in refs:
            if ref.split("-")[0] not in families:
                continue
            census["judged"] += 1
            if ref not in lanes:
                out.append(f"держатель коллекции {stem} называет полосу {ref}, а модуль кейсов "
                           f"{stem}.py её не несёт ни одним кейсом — полоса снята либо не "
                           f"заведена, и переутверждать задаче нечего")
    return out, census


def reconcile_producer_ledger(stems: set[str],
                              ledger: Ledger | None = None) -> list[str]:
    """Сверка ведомости с деревом В ОБЕ СТОРОНЫ."""
    ledger = PRODUCER_LEDGER if ledger is None else ledger
    out = []
    for stem in sorted(stems - set(ledger)):
        out.append(f"коллекция {stem} есть в дереве, а решения о её производителе "
                   f"не записано — перепись напечатала бы адрес вместо вердикта")
    for stem in sorted(set(ledger) - stems):
        out.append(f"запись про {stem} пережила свой предмет — такой коллекции в "
                   f"дереве нет, и прощать/объявлять нечего")
    for stem, (cat, why, _holder) in sorted(ledger.items()):
        if cat not in PRODUCER_CATEGORIES:
            out.append(f"запись про {stem} называет категорию {cat!r} вне закрытого "
                       f"словаря {sorted(PRODUCER_CATEGORIES)}")
        if not why.strip():
            out.append(f"запись про {stem} без довода — категория без довода есть "
                       f"мнение, а не решение")
    return out


def ledger_matches_ceremony(ceremony_need: dict[str, list[str]],
                            ledger: Ledger | None = None
                            ) -> list[str]:
    """Категория A у коллекции, требующей ЦЕРЕМОНИИ ЧЕЛОВЕКА, — находка.

    Сверка идёт в ОДНУ сторону намеренно. «A требует церемонии» — противоречие
    самой ведомости, и оно машинно разрешимо. Обратное («B не требует церемонии»)
    находкой НЕ объявляется: у B бывает и другое препятствие — недостижимый
    внешний поставщик, — и предикат, объявивший это расхождением, краснел бы на
    верной записи.
    """
    ledger = PRODUCER_LEDGER if ledger is None else ledger
    out = []
    for stem, keys in sorted(ceremony_need.items()):
        if not keys or stem not in ledger:
            continue
        if ledger[stem][0] == "A":
            out.append(
                f"коллекция {stem} объявлена категорией A (производитель — служба, "
                f"переезжает машинным посевом), а читает предъявителя ЦЕРЕМОНИИ "
                f"({', '.join(keys)}): машинный посев его не производит ни при "
                f"каком устройстве, значит это B")
    return out


# ─────────────── ПОЗИЦИИ ПРИЁМОК УРОВНЯ E (kaname#449) ──────────────────────
#
# Каталог приёмок относительно корня дерева: у синтетических деревьев
# самопроверки он свой, поэтому путь выводится от каталога набора, а не от ROOT.
ACCEPTANCE_REL = pathlib.Path("docs") / "engineering" / "acceptance"

# Словарь уровней — объединение легенд приёмок, выведенное обходом каталога, а не
# по памяти: E — наблюдаемо снаружи (стенд: слушатель службы либо край); I —
# изнутри процесса (интеграционный); G — гейт дерева; K — снаружи через край
# платформы (легенда account-id-may-be-supplied-at-create, kaname#549); P —
# свойство дерева, проверяемое переписью; U — модульный. Уровень — одиночная
# латинская заглавная.
LEVELS = "EIGKPU"
# СКВОЗНЫЕ уровни — наблюдаемые снаружи процесса: позиция любого из них обязана
# нестись кейсом, долгом либо домом. K сквозной так же, как E, — только его стенд
# платформы, и без этого множества позиция K выпала бы из переписи молча.
THROUGH_LEVELS = "EK"
_LV = rf"[{LEVELS}](?![A-Za-z0-9])"
# Одиночная латинская заглавная в ХВОСТЕ за перечнем: уровень за незнакомым
# разделителем («I / E», «(I, E)») либо буква вне словаря за знакомым («I + X»)
# были бы потеряны разбором молча. Поэтому хвост судится любой одиночной
# заглавной, а не только буквой словаря.
_LEVEL_IN_TAIL_RE = re.compile(r"(?<![A-Za-z0-9])[A-Z](?![A-Za-z0-9])")

# ЗАКОННЫХ ФОРМ ЗАГОЛОВКА СЦЕНАРИЯ ТРИ (kaname#449, опыт J4), и каждая выведена
# обходом `docs/engineering/acceptance/*.md`:
#   prefix — `**ID: IC-SECRET-01** · I + E — …`: перечень между разделителями;
#   titled — `**Ф3-08 — заголовок** · E + I`: перечень в конце строки, уровни
#            разделены « + » либо « · », за перечнем бывает хвост — пометка
#            редакции `· *новый*`, ссылка `(→ **Ф11-02**)`, довод `— **…**`;
#   parens — `**CRED-CAP-04 (I, управляемые часы).**`: перечень в скобках, за ним
#            бывает примечание после запятой.
# Прежний распознаватель знал одну prefix: позиция E формы titled давала код 0 и
# «позиций 7», пока DoD шести приёмок называл 132 такие позиции.
#
# У каждой формы два выражения. «Несёт перечень» — после разделителя стоит
# одиночная латинская заглавная; «разобрана» — перечень прочитан целиком. Строка,
# несущая перечень и не разобранная, — НЕЗНАКОМАЯ форма, и она называется, а не
# отбрасывается: разбор, молча пропустивший форму, дал бы «позиций E ноль».
# Заголовок, где после разделителя идёт довод словами («· отрицание; близнец —
# …», «(RED)», «(`kacho#1`)»), перечня уровней не несёт и позицией не является.
_BOLD_TITLE = r"(?:[^*]|\*(?!\*))+"
# «Несёт перечень» у формы parens сужен по форме УРОВНЯ, а не ID (kaname#903):
# уровень — одиночная заглавная, за ней не буква и не цифра, как у `_LV`. Проза
# «**Сейчас (S6):** …» перечня не несёт (`S6` — не одиночная заглавная) и молчит,
# а заголовок с настоящим уровнем и ID любой формы (`SYN36`, `syn-36`, `SYN_36`)
# остаётся позицией либо незнакомой формой: сужение по форме ID глушило его
# молча, хотя та же строка формы titled — позиция.
_PARENS_LEVEL = r"[A-Z](?![A-Za-z0-9])"
SCENARIO_FORMS: tuple[tuple[str, str, re.Pattern, re.Pattern], ...] = (
    ("prefix", "«**ID: <ID>** · <уровни> — …»",
     re.compile(r"^\*\*ID: [^*]+\*\* · [A-Z](?![A-Za-z])"),
     re.compile(rf"^\*\*ID: (?P<id>[^*\s]+)\*\* · (?P<lv>{_LV}(?: \+ {_LV})*) — ")),
    ("titled", "«**<ID> — <заголовок>** · <уровни>»",
     re.compile(rf"^\*\*[^*\s]+ — {_BOLD_TITLE}\*\* · [A-Z](?![A-Za-z])"),
     re.compile(rf"^\*\*(?P<id>[^*\s]+) — {_BOLD_TITLE}\*\* · "
                rf"(?P<lv>{_LV}(?:(?: \+ | · ){_LV})*)(?P<tail>(?:\s.*)?)$")),
    ("parens", "«**<ID> (<уровни>).**»",
     re.compile(rf"^\*\*[^*\s]+ \({_PARENS_LEVEL}"),
     re.compile(rf"^\*\*(?P<id>[^*\s]+) \((?P<lv>{_LV}(?: \+ {_LV})*)"
                rf"(?P<tail>(?:, [^)]*)?)\)\.?\*\*")),
)
_LEVEL_SEP_RE = re.compile(r" [+·] ")


def acceptance_positions(acceptance: pathlib.Path
                         ) -> tuple[dict[str, str], int, list[str], dict[str, list[int]]]:
    """Позиции сквозных уровней (`THROUGH_LEVELS`): ID → приёмка; сколько приёмок
    прочитано; незнакомые формы; по каждой форме — [заголовков с перечнем прочитано,
    из них сквозных]."""
    positions: dict[str, str] = {}
    unknown: list[str] = []
    forms: dict[str, list[int]] = {key: [0, 0] for key, *_ in SCENARIO_FORMS}
    docs = sorted(acceptance.glob("*.md")) if acceptance.is_dir() else []
    for doc in docs:
        for n, line in enumerate(doc.read_text(encoding="utf-8").splitlines(), 1):
            for key, _label, leveled, head in SCENARIO_FORMS:
                if not leveled.match(line):
                    continue
                m = head.match(line)
                tail = (m.groupdict().get("tail") or "") if m else ""
                if m is None or _LEVEL_IN_TAIL_RE.search(tail):
                    unknown.append(f"{doc.name}:{n}: {line[:90]}")
                    break
                forms[key][0] += 1
                if set(_LEVEL_SEP_RE.split(m.group("lv"))) & set(THROUGH_LEVELS):
                    forms[key][1] += 1
                    positions[m.group("id")] = doc.name
                break
    return positions, len(docs), unknown, forms


def carried_positions(cases: pathlib.Path, ids: set[str]) -> dict[str, list[str]]:
    """Какой модуль кейсов несёт позицию: ID стоит в СТРОКОВОМ ЛИТЕРАЛЕ модуля.

    Модуль читается разобранным (`ast`): комментарий, объясняющий, почему позиции
    здесь нет, позицию не несёт. Докстрока — литерал, и она в счёт: трасса
    «сценарий — кейс» в наборе пишется именно ею.
    """
    import ast as _ast
    out: dict[str, list[str]] = {}
    pats = {i: re.compile(r"(?<![A-Z0-9-])" + re.escape(i) + r"(?![0-9])") for i in ids}
    for mod in sorted(cases.glob("*.py")) if cases.is_dir() else []:
        tree = _ast.parse(mod.read_text(encoding="utf-8"), filename=str(mod))
        text = "\n".join(n.value for n in _ast.walk(tree)
                         if isinstance(n, _ast.Constant) and isinstance(n.value, str))
        for i, pat in pats.items():
            if pat.search(text):
                out.setdefault(i, []).append(mod.stem)
    return out


def reconcile_scenario_debt(newman: pathlib.Path, debt: ScenarioDebt,
                            home: ScenarioHome | None = None
                            ) -> tuple[list[str], dict[str, str], dict[str, list[str]], int,
                                       dict[str, list[int]]]:
    """Позиции уровня E против модулей кейсов, записей долга и записей о доме в
    другом репозитории — В ОБЕ СТОРОНЫ.

    Возвращает находки, позиции (ID → приёмка), кто их несёт, сколько приёмок
    прочитано и перепись заголовков по формам.
    """
    home = {} if home is None else home
    positions, docs, unknown, forms = acceptance_positions(newman.parents[1] / ACCEPTANCE_REL)
    carried = carried_positions(newman / "cases", set(positions) | set(debt) | set(home))
    out = [f"заголовок сценария в незнакомой форме (уровни не разобраны): {u}" for u in unknown]
    for sid in sorted(positions):
        if sid not in carried and sid not in debt and sid not in home:
            out.append(f"позиция {sid} ({positions[sid]}) объявлена сквозной (уровень E либо K), а ни "
                       f"кейса в модулях набора, ни записи долга, ни записи о доме в другом "
                       f"репозитории о ней нет")
    for sid, (case, step) in sorted(home.items()):
        if sid not in positions:
            out.append(f"запись дома позиции {sid} пережила предмет: сквозного сценария (E либо K) с таким "
                       f"ID нет ни в одной приёмке")
        elif sid in carried:
            out.append(f"запись дома позиции {sid} пережила предмет: её несёт модуль "
                       f"{', '.join(carried[sid])} этого дерева — запись снимается тем же "
                       f"изменением, что завело кейс")
        if sid in debt:
            out.append(f"позиция {sid} записана и долгом, и домом в другом репозитории — исход "
                       f"у позиции один")
        cm, sm = HOME_CASE_RE.match(case), HOME_STEP_RE.match(step)
        if cm is None:
            out.append(f"кейс дома позиции {sid} вне закрытой формы «PRO-Robotech/<другой "
                       f"репозиторий>:<путь>/tests/newman/cases/<модуль>.py» либо «…:<путь>/"
                       f"e2e/specs/<проба>.spec.ts»: {case!r}")
        if sm is None:
            out.append(f"шаг дома позиции {sid} вне закрытой формы «PRO-Robotech/<репозиторий>:"
                       f".github/workflows/<файл>.yml «<имя шага>»»: {step!r}")
        if cm and sm and cm.group(1) != sm.group(1):
            out.append(f"шаг дома позиции {sid} назван в другом репозитории, чем её кейс: "
                       f"{sm.group(1)} против {cm.group(1)}")
    for sid, (why, holder) in sorted(debt.items()):
        if sid not in positions:
            out.append(f"запись долга позиции {sid} пережила предмет: сквозного сценария (E либо K) с таким "
                       f"ID нет ни в одной приёмке")
        elif sid in carried:
            out.append(f"запись долга позиции {sid} пережила предмет: её несёт модуль "
                       f"{', '.join(carried[sid])} — запись снимается тем же изменением, что "
                       f"завело кейс")
        if not why.strip():
            out.append(f"запись долга позиции {sid} без довода")
        if not HOLDER_RE.match(holder):
            out.append(f"держатель позиции {sid} вне закрытой формы "
                       f"«PRO-Robotech/<репозиторий>#<номер> — <что сделает>»: {holder!r}")
    return out, positions, carried, docs, forms


# ДЕРЖАТЕЛЬ ЖИВ (kaname#468). Запись долга держится задачей, которая её снимет, и
# форма держателя (`HOLDER_RE`) этого не доказывает: закрытая задача ничего не
# снимет, а запись остаётся зелёной. Так и было — Ф5-24 держала закрытая
# kacho#1269, Ф5-12 — закрытая kaname#475. Состояние задачи спрашивается у трекера
# через обёртку, которую подставляет вызывающий: самопроверка — словарём, перепись
# дерева — `gh`. Трекер не ответил — третий исход («не выполнилось»), а не молчание
# и не находка.
HolderTracker = Callable[[str], "str | None"]


def gh_issue_state(ref: str) -> str | None:
    """Состояние задачи `owner/repo#N` по трекеру: 'open' | 'closed' | None (не ответил)."""
    repo, _, num = ref.partition("#")
    try:
        proc = subprocess.run(["gh", "api", f"repos/{repo}/issues/{num}", "--jq", ".state"],
                              capture_output=True, text=True, timeout=60)
    except (OSError, subprocess.TimeoutExpired):
        return None
    state = proc.stdout.strip()
    return state if proc.returncode == 0 and state in ("open", "closed") else None


def reconcile_holder_liveness(ledger: Ledger, scenario_debt: ScenarioDebt, tracker: HolderTracker
                              ) -> tuple[list[str], list[str], dict[str, int]]:
    """Держатель каждой записи — открытая задача. Закрытый — находка с именами записей.

    Возвращает (находки, не выполнилось, перепись). Один держатель спрашивается один
    раз, сколько бы записей он ни держал."""
    held: dict[str, list[str]] = {}
    for stem, row in ledger.items():
        m = HOLDER_REF_RE.match(row[2] or "")
        if m:
            held.setdefault(m.group(1), []).append(f"коллекции {stem}")
    for sid, (_why, holder) in scenario_debt.items():
        m = HOLDER_REF_RE.match(holder or "")
        if m:
            held.setdefault(m.group(1), []).append(f"позиции {sid}")
    bad: list[str] = []
    unmet: list[str] = []
    census = {"holders": len(held), "records": sum(len(v) for v in held.values()),
              "open": 0, "closed": 0, "unknown": 0}
    for ref, records in sorted(held.items()):
        state = tracker(ref)
        if state == "open":
            census["open"] += 1
        elif state == "closed":
            census["closed"] += 1
            bad.append(f"держатель {ref} закрыт, а записи держатся им ({len(records)}): "
                       f"{', '.join(records)} — закрытая задача записи не снимет; передать "
                       f"живому держателю по предмету записи либо снять запись с предметом")
        else:
            census["unknown"] += 1
            unmet.append(f"держатель {ref} ({len(records)} записей): трекер не ответил о "
                         f"состоянии задачи — живость не выполнилась")
    return bad, unmet, census


def run(newman: pathlib.Path, workflows: pathlib.Path | None = None,
        ledger: Ledger | None = None, scenario_debt: ScenarioDebt | None = None,
        scenario_home: ScenarioHome | None = None,
        absence_claims: AbsenceClaims | None = None,
        tracker: HolderTracker | None = None) -> int:
    # Ведомости позиций, как и ведомость производителя, — ПАРАМЕТРЫ. Объявленные
    # берутся только для объявленного дерева: синтетическая ведомость коллекций
    # значит синтетическое дерево, и объявленных позиций у него нет.
    declared_tree = ledger is None and scenario_debt is None and scenario_home is None
    if scenario_debt is None:
        scenario_debt = SCENARIO_DEBT if ledger is None else {}
    if scenario_home is None:
        scenario_home = SCENARIO_HOME if ledger is None else {}
    if workflows is None:
        workflows = ROOT / ".github" / "workflows"
    try:
        (cols, wfs, runs, scripts, minted, mute, runnable, blocked,
         by_surface, by_blocker, by_state, ceremony_need) = survey(newman, workflows)
    except ValueError as e:
        print(f"ОТКАЗ: {e}.", file=sys.stderr)
        return 1
    except ModuleNotFoundError as e:
        print(f"УСЛОВИЕ НЕ СОЗДАНО: нет разборщика YAML ({e}) — объявление конвейера "
              f"не прочитано, величина «гоняется» НЕ ИЗМЕРЕНА.", file=sys.stderr)
        return RC_UNMET
    except Unmet as e:
        print(f"УСЛОВИЕ НЕ СОЗДАНО: {e}.", file=sys.stderr)
        return RC_UNMET

    drift = reconcile_producer_ledger({stem for stem, *_ in
                                       [*runnable, *blocked]}, ledger)
    # КАТЕГОРИЯ СВЕРЯЕТСЯ С ТРЕБОВАНИЕМ ЦЕРЕМОНИИ, А НЕ ТОЛЬКО ОБЪЯВЛЯЕТСЯ.
    # Ведомость сама определяет B как «служба, но нужен ЧЕЛОВЕЧЕСКИЙ
    # предъявитель». Коллекция, объявленная A и читающая предъявителя церемонии,
    # объявлена переводимой машинным посевом — то есть ОБЕЩАЕТ ВОЗМОЖНОСТЬ,
    # неисполнимую by construction: машине поднять уровень нечем.
    # Цена названа: такая запись переносит коллекцию в план переезда, где её
    # нельзя закрыть ничем, и мера работы становится недостижимой.
    drift += ledger_matches_ceremony(ceremony_need, ledger)
    # ПРОИЗВОДИТЕЛЬ В КОНВЕЙЕРЕ: шаг либо держатель, по каждой позиции и в обе
    # стороны (`reconcile_holders`). Судится по объявлению конвейера (`runs`), а не
    # по половинам переписи: у гоняемой шагом коллекции бывают и препятствия — их
    # расхождение со шагом держит `pipeline_claims_test.py`.
    all_stems = {stem for stem, *_ in [*runnable, *blocked]}
    drift += reconcile_holders(all_stems, runs, ledger)
    # ПОЛОСА, НАЗВАННАЯ ДЕРЖАТЕЛЕМ, — утверждение о модуле кейсов, и оно
    # сверяется с модулем, а не с памятью о нём (`reconcile_holder_lanes`).
    lane_drift, lane_census = reconcile_holder_lanes(newman / "cases", ledger)
    drift += lane_drift
    # ПОЗИЦИЯ ПРИЁМКИ — мельче коллекции, и её долг судится отдельно (kaname#449).
    pos_drift, positions, carried, acc_docs, acc_forms = reconcile_scenario_debt(
        newman, scenario_debt, scenario_home)
    if declared_tree and acc_docs == 0:
        pos_drift.append(f"приёмок в {ACCEPTANCE_REL} прочитано 0 — перепись позиций "
                         f"беспредметна: «долга позиций нет» значило бы «ничего не прочитано»")
    drift += pos_drift
    # ДОВОД ОБ ОТСУТСТВИИ судится деревом (kaname#643): по записям долга позиций и
    # по записям ведомости производителя.
    claims = ABSENCE_CLAIMS if absence_claims is None else absence_claims
    reasons = {f"позиции {sid}": why for sid, (why, _h) in scenario_debt.items()}
    reasons.update({f"коллекции {stem}": row[1] for stem, row in
                    (PRODUCER_LEDGER if ledger is None else ledger).items()})
    abs_drift, abs_census = reconcile_absence_claims(newman.parents[1], reasons, claims)
    # Запись предиката без довода истекает сама: на объявленном дереве и всякий
    # раз, когда ведомость предикатов передана явно (синтетика самопроверки).
    if declared_tree or absence_claims is not None:
        for name in sorted(set(claims) - set(abs_census["used_names"])):
            abs_drift.append(f"предикат довода «{name}» (`ABSENCE_CLAIMS`) не называет ни один довод "
                             f"ведомостей — запись пережила свой довод")
    drift += abs_drift
    # ДЕРЖАТЕЛЬ ЖИВ (kaname#468): на объявленном дереве трекер по умолчанию — `gh`;
    # синтетическое дерево без обёртки трекера не судится, и это печатается.
    if tracker is None and declared_tree:
        tracker = gh_issue_state
    live_unmet: list[str] = []
    live_census: dict[str, int] | None = None
    if tracker is not None:
        live_bad, live_unmet, live_census = reconcile_holder_liveness(
            PRODUCER_LEDGER if ledger is None else ledger, scenario_debt, tracker)
        drift += live_bad
    if drift:
        print("ОТКАЗ: ведомость производителя разошлась с деревом:", file=sys.stderr)
        for d in drift:
            print(f"  · {d}", file=sys.stderr)
        return 1

    # «Здесь» — стенды службы, которые поднимает её конвейер: автономный и стенд
    # чарта посадки `own`. Какой именно гоняет коллекцию, называет её строка ниже.
    print("===== сквозной набор на стендах службы (автономный · посадка own): что гоняется, а что нет =====")
    print(f"коллекций в дереве: {len(cols)}")
    print(f"  гоняется здесь:    {len(runnable)}")
    print(f"  НЕ гоняется здесь: {len(blocked)}")
    print()
    # ОБЪЁМ ОСМОТРЕННОГО — рядом с величиной: «гоняется N», напечатанное
    # переписью, которая конвейер не читает, измеряет не то, что называет.
    print(f"объявлений конвейера прочитано: {len(wfs)} "
          f"({', '.join(f.name for f in wfs)})")
    print(f"коллекций гоняют шаги конвейера: {len(runs)}")
    for stem, where in sorted(runs.items()):
        print(f"  · {stem} ← {'; '.join(where)}")
    # ОСТАТОК И ЕГО ДЕРЖАТЕЛИ — ТЕМ ЖЕ ВЫВОДОМ: предикат «каждая из M−N названа
    # с держателем» читается здесь, а не прочтением ведомости. Сверка выше
    # уже отказала бы на позиции без держателя, поэтому «назван у K» при K < M−N
    # здесь не печатается никогда — строка есть свидетель, а не второй суд.
    unrun = sorted(all_stems - set(runs))
    by_holder: dict[str, list[str]] = {}
    for stem in unrun:
        m = HOLDER_REF_RE.match(holder_of(stem, ledger))
        by_holder.setdefault(m.group(1) if m else "—", []).append(stem)
    held_n = sum(len(v) for k, v in by_holder.items() if k != "—")
    print(f"НЕ гоняет ни один шаг: {len(unrun)} — держатель назван у {held_n}")
    print("по ДЕРЖАТЕЛЮ (задача, которая прогонит):")
    for ref, stems in sorted(by_holder.items(), key=lambda kv: (-len(kv[1]), kv[0])):
        print(f"  · {ref}: {len(stems)} ({', '.join(stems)})")
    # Объём осмотренного сверкой полос — рядом со сводом держателей: «ноль
    # находок» без него не отличает «названа живая полоса» от «не судилось ничего».
    print(f"доводы об отсутствии: прочитано {abs_census['claims']} · с предикатом "
          f"{abs_census['judged']} · осмотрено файлов {abs_census['files']}")
    print(f"полосы, названные держателями: держателей прочитано {lane_census['holders']} · "
          f"полос названо {lane_census['named']} · из них судимо модулем кейсов "
          f"{lane_census['judged']}")
    print()
    print("по АДРЕСАЦИИ (к чьему базовому адресу стучатся шаги):")
    for s, n in sorted(by_surface.items(), key=lambda kv: -kv[1]):
        print(f"  {n:3d}  {s}")
    print()
    by_producer: dict[str, int] = {}
    for stem, *_ in [*runnable, *blocked]:
        cat, _why = producer_of(stem, ledger)
        label = f"{cat} — {PRODUCER_CATEGORIES[cat]}"
        by_producer[label] = by_producer.get(label, 0) + 1
    print("по ПРОИЗВОДИТЕЛЮ (объявлено ведомостью, разрез #24):")
    for label, n in sorted(by_producer.items()):
        print(f"  {n:3d}  {label}")
    print()
    # РАСХОЖДЕНИЕ ДВУХ ВЕЛИЧИН — ОТДЕЛЬНОЕ ЧИСЛО, а не то, что читатель обязан
    # сложить сам: адрес края при производителе-службе и есть предмет переезда.
    mismatch = [stem for stem, *_ in [*runnable, *blocked]
                if producer_of(stem, ledger)[0] in ("A", "B")
                and _surface_of_stem(stem, runnable, blocked) == SURFACE_EDGE]
    print(f"адресуется к краю, а производитель — служба: {len(mismatch)}")
    print("  (это и есть предмет переезда; ярлык адреса о производителе не говорит)")
    print()
    print("по препятствию (одна коллекция может иметь несколько):")
    for b, n in sorted(by_blocker.items(), key=lambda kv: -kv[1]):
        print(f"  {n:3d}  {b}")
    print()
    # СОСТОЯНИЕ КЛЮЧА — ОТДЕЛЬНОЙ ПЕРЕПИСЬЮ. Одно число «непосеянных» скрыло бы
    # то, ради чего перепись и делается: пустой ключ падает громко (страж набора
    # утверждает его по имени), литерал чужого стенда — тихо и ПОХОЖЕ НА ДЕФЕКТ
    # ПРОДУКТА, а отсутствующей строки шаблона не хватает раньше значения.
    print("по СОСТОЯНИЮ непосеянного ключа (вхождений по всем коллекциям):")
    for state in (KEY_STATE_EMPTY, KEY_STATE_LITERAL, KEY_STATE_ABSENT):
        print(f"  {state}: {by_state[state]}")
    print()
    print(f"посев общих фикстур: {'есть' if scripts else 'ОТСУТСТВУЕТ'} "
          f"({len(scripts)} скрипт(ов) в authz-fixtures/), "
          f"ключей окружения он пишет: {sum(len(v) for v in minted.values())}")
    for surface, keys in sorted(minted.items()):
        print(f"  · для поверхности «{surface}»: {len(keys)} ключ(ей)")
    for script in scripts:
        print(f"  · {script.name}")
    for m in mute:
        print(f"  · НЕ НАЗВАЛ СВОИХ КЛЮЧЕЙ — {m}")
    print()
    if runnable:
        print("ГОНЯЕТСЯ ЗДЕСЬ (и КАКИМ шагом конвейера):")
        for stem, surface, where in runnable:
            cat, why = producer_of(stem, ledger)
            print(f"  · {stem} — адресация: {surface}; производитель: "
                  f"{cat} ({PRODUCER_CATEGORIES[cat]}) — {why}")
            for w in where:
                print(f"      ← {w}")
        print()
    print("НЕ ГОНЯЕТСЯ ЗДЕСЬ (по каждой позиции — причина):")
    for stem, surface, bl in blocked:
        cat, why = producer_of(stem, ledger)
        print(f"  · {stem} [адресация: {surface}; производитель: "
              f"{cat} ({PRODUCER_CATEGORIES[cat]})] — {why}")
        for b in bl:
            print(f"      — {b}")
        holder = holder_of(stem, ledger)
        if holder:
            print(f"      держатель: {holder}")
    print()
    # ПОЗИЦИИ ПРИЁМОК УРОВНЯ E — числом и по каждой: гоняется ли модуль, который
    # её несёт, либо чем и кем записан её долг.
    ran = [sid for sid in positions if any(runs.get(st) for st in carried.get(sid, []))]
    built = [sid for sid in positions if sid in carried and sid not in ran]
    homed = [sid for sid in positions if sid not in carried and sid in scenario_home]
    owed = [sid for sid in positions if sid not in carried and sid not in scenario_home]
    print(f"ПОЗИЦИИ ПРИЁМОК СКВОЗНЫХ УРОВНЕЙ E И K (прогон на стенде): приёмок прочитано {acc_docs}, "
          f"позиций {len(positions)} — гоняется {len(ran)} · собрана, коллекция не гоняется "
          f"{len(built)} · долг {len(owed)} · в доме другого репозитория {len(homed)}")
    # Дом другого репозитория — ЗАПИСЬ, а не измерение: его дерева рядом нет, и
    # сказать это надо там же, где названо число.
    print(f"  дом в другом репозитории: записей {len(homed)}; сверка с деревом дома здесь НЕ "
          f"выполняется — кейс и шаг названы записью, их наличие в доме этот прогон не измерил")
    # Прочитанное ПО КАЖДОЙ ФОРМЕ: «позиций N» без него не отличает «форма не
    # встречается» от «форму не читают» — ровно тот случай, что был слеп (J4).
    print("  формы заголовка сценария (с перечнем уровней прочитано · из них сквозных, E либо K): "
          + "; ".join(f"{label} {acc_forms[key][0]} · {acc_forms[key][1]}"
                      for key, label, *_ in SCENARIO_FORMS))
    for sid in sorted(positions):
        if sid in carried:
            where = "; ".join(w for st in carried[sid] for w in runs.get(st, []))
            state = (f"гоняется ← {where}" if where else
                     f"собрана в {', '.join(carried[sid])}, коллекция не гоняется "
                     f"(её держатель — строкой выше)")
            print(f"  · {sid} [{positions[sid]}] — {state}")
        elif sid in scenario_home:
            case, step = scenario_home[sid]
            print(f"  · {sid} [{positions[sid]}] — в доме {HOME_CASE_RE.match(case).group(1)}: "
                  f"кейс {case}, шаг {step}")
        else:
            why, holder = scenario_debt[sid]
            print(f"  · {sid} [{positions[sid]}] — ДОЛГ: {why}")
            print(f"      держатель: {holder}")
    print()
    print("ЧТО ЭТОТ ДОЛГ ЗНАЧИТ, СКАЗАНО ПРЯМО:")
    print("  · прогон автономного стенда проверяет свойства, чей производитель —")
    print("    САМА служба (её фронты, их непроницаемость, рубеж, разбор доступа,")
    print("    набор ключей своей чеканки, честный отказ не той форме входа).")
    print("    Список — stand-assert.py;")
    print("  · свойства КРАЯ платформы здесь не проверяются вовсе и остаются")
    print("    предметом её конвейера;")
    print("  · полоса личности у службы одна — `own` (внешнего поставщика нет ВООБЩЕ,")
    print("    kaname#424); автономный стенд идёт на ней, людей заводит полосой входа")
    print("    листом края стенда, а сквозной набор полосы входа и церемонии гоняет")
    print("    стенд чарта — задание `chart-own` (врезка в .github/scripts/stand-own.sh);")
    print("  · человеческого предъявителя не куёт ни один посев: волна церемонии")
    print("    печатает свой долг сама (tests/authz-fixtures/ceremony_credentials.py --debt).")
    print()
    if live_census is None:
        print("живость держателей: НЕ СУДИЛАСЬ — обёртки трекера нет (синтетическое дерево)")
    else:
        print(f"живость держателей: держателей {live_census['holders']} · записей "
              f"{live_census['records']} · открыты {live_census['open']} · закрыты "
              f"{live_census['closed']} · трекер не ответил {live_census['unknown']}")
    if live_unmet:
        print("УСЛОВИЕ НЕ СОЗДАНО — живость держателей не выполнилась:", file=sys.stderr)
        for u in live_unmet:
            print(f"  · {u}", file=sys.stderr)
        return RC_UNMET
    return 0


# ─────────────────────────── доказательство инъекцией ────────────────────────

_F: list[str] = []


def _c(label: str, ok: bool, detail: str = "") -> None:
    print(f"  {'ok  ' if ok else 'FAIL'} {label}")
    if not ok:
        _F.append(label)
        if detail:
            print(f"       {detail}")


def _mk(tmp: pathlib.Path, cols: dict[str, str], tmpl: dict[str, str]) -> pathlib.Path:
    newman = tmp / "tests" / "newman"
    (newman / "collections").mkdir(parents=True, exist_ok=True)
    (newman / "environments").mkdir(parents=True, exist_ok=True)
    for name, body in cols.items():
        (newman / "collections" / f"{name}.postman_collection.json").write_text(
            body, encoding="utf-8")
    (newman / "environments" / "local.postman_environment.template.json").write_text(
        json.dumps({"values": [{"key": k, "value": v} for k, v in tmpl.items()]}),
        encoding="utf-8")
    return newman


def _wf(tmp: pathlib.Path, runs: list[str]) -> pathlib.Path:
    """Синтетическое объявление конвейера: по шагу на каждую гоняемую коллекцию."""
    wf = tmp / ".github" / "workflows"
    wf.mkdir(parents=True, exist_ok=True)
    steps = "".join(
        f"      - name: коллекция {r} гоняется\n"
        f"        run: |\n"
        f"          cd tests/newman\n"
        f"          ./scripts/run.sh --service {r}\n"
        for r in runs) or "      - run: echo нечего\n"
    (wf / "e2e-newman.yml").write_text(
        "name: proof\non: [push]\njobs:\n  stand:\n    steps:\n" + steps,
        encoding="utf-8")
    return wf


def _st_ledger(newman: pathlib.Path, workflows: pathlib.Path | None) -> Ledger:
    """Синтетическая ведомость для синтетического дерева: одна запись на коллекцию.

    Самопроверка судит ДРУГИЕ оси; требовать от неё объявленных решений о
    коллекциях, которых в дереве нет, значило бы уронить её на предмете, к
    которому она не относится. Сверку самой ведомости держат оси 10 и 11 ниже —
    там расхождение вносится НАМЕРЕННО; сверку держателя — ось 16.

    Держатель ставится ровно там, где его требует сверка: у коллекции, которую
    шаг синтетического конвейера не гоняет. Иначе оси о посеве и адресации падали
    бы на держателе, к которому они не относятся.
    """
    declared = template_keys(newman)
    try:
        runs = pipeline_runs(workflows) if workflows is not None else {}
    except (Unmet, ModuleNotFoundError):
        runs = {}
    out: Ledger = {}
    for p in sorted((newman / "collections").glob("*.postman_collection.json")):
        stem = p.name.replace(".postman_collection.json", "")
        text = p.read_text(encoding="utf-8")
        own = set(OWN_KEY_RE.findall(text))
        # Категория выводится ТЕМ ЖЕ правилом, что сверяет `ledger_matches_ceremony`:
        # иначе оси 7 и 7б (фикстуры с предъявителем церемонии) падали бы на
        # проверке классификации, к которой они не относятся. Сама проверка от
        # этого не становится вакуумной — её ось ниже подаёт ведомость ЯВНО.
        cer = any(key_state(k, declared, own) is not None and is_ceremony_key(k)
                  for k in used_keys(text))
        holder = "" if runs.get(stem) else "PRO-Robotech/kaname#1 — синтетика самопроверки"
        out[stem] = ("B" if cer else "A", "синтетика самопроверки", holder)
    return out


def _st_run(newman: pathlib.Path, workflows: pathlib.Path | None = None,
            ledger: Ledger | None = None) -> int:
    return run(newman, workflows=workflows,
               ledger=_st_ledger(newman, workflows) if ledger is None else ledger)


def self_test() -> int:
    import io
    import contextlib
    import tempfile
    print("newman-suite-debt: доказательство способности упасть")
    with tempfile.TemporaryDirectory(prefix="debt-proof-") as td:
        tmp = pathlib.Path(td)

        # Ось 1: пустой обход — ОТКАЗ, а не «долга нет».
        empty = _mk(tmp / "empty", {}, {"baseUrl": "http://x"})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = _st_run(empty, workflows=_wf(tmp / "empty", runs=[]))
        _c("ноль коллекций — код 1, а НЕ 0", rc == 1, buf.getvalue()[-200:])
        _c("и отказ называет беспредметность", "беспредметна" in buf.getvalue())

        # Ось 2: коллекция БЕЗ препятствий обязана попасть в «гоняется».
        own = ('{"item":[{"name":"s","request":{"url":{"raw":"{{ownRestBaseUrl}}/x"}}}]}')
        t2 = _mk(tmp / "own", {"own-only": own},
                 {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = _st_run(t2, workflows=_wf(tmp / "own", runs=["own-only"]))
        out = buf.getvalue()
        _c("коллекция без препятствий — код 0", rc == 0)
        _c("она в «гоняется здесь»", "гоняется здесь:    1" in out, out[:400])
        _c("и её поверхность названа службой", "собственный REST-фронт" in out)

        # Ось 3: ЗАКОННЫЙ БЛИЗНЕЦ — та же коллекция, но читает пустой ключ посева.
        own2 = ('{"item":[{"name":"s","request":{"url":{"raw":"{{ownRestBaseUrl}}/x"}},'
                '"event":[{"listen":"test","script":{"exec":['
                '"pm.environment.get(\'jwtAccountAdminA\')"]}}]}]}')
        t3 = _mk(tmp / "own-seeded", {"own-seeded": own2},
                 {"ownRestBaseUrl": "https://localhost:9098", "jwtAccountAdminA": "",
                  "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t3, workflows=_wf(tmp / "own-seeded", runs=["own-seeded"]))
        out = buf.getvalue()
        _c("та же коллекция с пустым ключом посева — в «НЕ гоняется»",
           "НЕ гоняется здесь: 1" in out, out[:400])
        _c("и причина названа посевом", "машинный посев" in out, out[:600])

        # Ось 3б: ПОСЕВ СНИМАЕТ ПРЕПЯТСТВИЕ ПОКЛЮЧЕВО, а не одним флагом.
        # Два синтетических посева: один пишет ИМЕННО тот ключ, что читает
        # коллекция, второй — соседний. Различие ровно в одном факте, и оно
        # обязано двигать коллекцию между половинами переписи.
        for lane, minted_key, expect_runs in (("covered", "jwtAccountAdminA", True),
                                              ("other", "jwtSomethingElse", False)):
            base = tmp / f"seed-{lane}"
            t3b = _mk(base, {"own-seeded": own2},
                      {"ownRestBaseUrl": "https://localhost:9098",
                       "jwtAccountAdminA": "", "runId": ""})
            fixtures = t3b.parent / "authz-fixtures"
            fixtures.mkdir(parents=True, exist_ok=True)
            script = fixtures / "seed_probe.py"
            script.write_text(
                "import sys\n"
                "if '--minted-keys' in sys.argv:\n"
                f"    print({minted_key!r})\n"
                "elif '--minted-surface' in sys.argv:\n"
                "    print('служба (собственный REST-фронт)')\n",
                encoding="utf-8")
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t3b, workflows=_wf(base, runs=["own-seeded"]))
            out = buf.getvalue()
            _c(f"посев, пишущий {minted_key}: коллекция "
               f"{'ГОНЯЕТСЯ' if expect_runs else 'НЕ гоняется'}",
               (f"гоняется здесь:    {1 if expect_runs else 0}" in out
                and f"НЕ гоняется здесь: {0 if expect_runs else 1}" in out),
               out[:500])

        # Ось 3в: посев, который на вопрос НЕ ОТВЕЧАЕТ, в счёт не идёт и
        # называется отдельно — «посев есть, а что пишет, неизвестно» и «посева
        # нет» ведут читателя в разные места.
        mute_base = tmp / "seed-mute"
        t3c = _mk(mute_base, {"own-seeded": own2},
                  {"ownRestBaseUrl": "https://localhost:9098",
                   "jwtAccountAdminA": "", "runId": ""})
        mute_fixtures = t3c.parent / "authz-fixtures"
        mute_fixtures.mkdir(parents=True, exist_ok=True)
        (mute_fixtures / "seed_probe.py").write_text(
            "import sys\nsys.exit(2)\n", encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t3c, workflows=_wf(mute_base, runs=["own-seeded"]))
        out = buf.getvalue()
        _c("молчащий посев не снимает препятствия", "НЕ гоняется здесь: 1" in out,
           out[:400])
        _c("и назван отдельной строкой", "НЕ НАЗВАЛ СВОИХ КЛЮЧЕЙ" in out, out[:600])

        # ── Ось 3г: ПОСЕВ СНИМАЕТ ПРЕПЯТСТВИЕ ТОЛЬКО НА СВОЕЙ ПОВЕРХНОСТИ ───
        #
        # Совпадение ИМЕНИ ключа через два разных стенда — не производство ключа.
        # Посев этого дерева куёт `jwtAccountAdminA` на СОБСТВЕННОМ фронте службы;
        # коллекция КРАЯ читает ключ того же имени, но её предъявителя производит
        # чужой посев чужого стенда. Различие ровно в поверхности, и оно обязано
        # двигать коллекцию между половинами переписи.
        for lane, surface_decl, edge_runs in (
                ("own-surface", "служба (собственный REST-фронт)", False),
                ("edge-surface", SURFACE_EDGE, True)):
            base = tmp / f"surface-{lane}"
            edge_seeded = ('{"item":[{"name":"s","request":{"url":{"raw":'
                           '"{{baseUrl}}/iam/v1/x"}},'
                           '"event":[{"listen":"test","script":{"exec":['
                           '"pm.environment.get(\'jwtAccountAdminA\')"]}}]}]}')
            t3g = _mk(base, {"edge-seeded": edge_seeded},
                      {"baseUrl": "http://edge", "jwtAccountAdminA": "", "runId": ""})
            fixtures = t3g.parent / "authz-fixtures"
            fixtures.mkdir(parents=True, exist_ok=True)
            (fixtures / "seed_probe.py").write_text(
                "import sys\n"
                "if '--minted-keys' in sys.argv:\n"
                "    print('jwtAccountAdminA')\n"
                "elif '--minted-surface' in sys.argv:\n"
                f"    print({surface_decl!r})\n",
                encoding="utf-8")
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t3g, workflows=_wf(base, runs=["edge-seeded"]))
            out = buf.getvalue()
            _c(f"посев поверхности «{surface_decl}»: препятствие посева у коллекции "
               f"КРАЯ {'снято' if edge_runs else 'ОСТАЛОСЬ'}",
               ("машинный посев" in out) != edge_runs, out[:600])

        # Ось 3д: посев, не объявивший ПОВЕРХНОСТЬ, в счёт не идёт и назван.
        # Fail-closed: «ключи назвал, поверхность нет» и «поверхность края» ведут
        # читателя в разные места, а молча зачесть — значит вернуть совпадение имён.
        base = tmp / "surface-mute"
        own_seeded_edge = ('{"item":[{"name":"s","request":{"url":{"raw":'
                           '"{{ownRestBaseUrl}}/x"}},'
                           '"event":[{"listen":"test","script":{"exec":['
                           '"pm.environment.get(\'jwtAccountAdminA\')"]}}]}]}')
        t3d = _mk(base, {"own-seeded": own_seeded_edge},
                  {"ownRestBaseUrl": "https://localhost:9098",
                   "jwtAccountAdminA": "", "runId": ""})
        fx = t3d.parent / "authz-fixtures"
        fx.mkdir(parents=True, exist_ok=True)
        (fx / "seed_probe.py").write_text(
            "import sys\n"
            "if '--minted-keys' in sys.argv:\n"
            "    print('jwtAccountAdminA')\n",
            encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t3d, workflows=_wf(base, runs=["own-seeded"]))
        out = buf.getvalue()
        _c("посев без объявленной поверхности не снимает препятствия",
           "машинный посев" in out, out[:600])
        _c("и назван отдельной строкой", "НЕ НАЗВАЛ СВОЕЙ ПОВЕРХНОСТИ" in out, out[:700])

        # ── Ось 6: «ГОНЯЕТСЯ» ЧИТАЕТСЯ ИЗ ОБЪЯВЛЕНИЯ КОНВЕЙЕРА ──────────────
        #
        # Величина обязана измерять то, что называет. Прежняя редакция печатала
        # «гоняется здесь: N», не читая конвейер ВОВСЕ: снятие шага прогона из
        # `e2e-newman.yml` её не меняло, то есть она измеряла «ничто не мешает
        # гонять». Ось доказывает обратное ПАРОЙ: тот же тракт, шаг снят — и
        # коллекция уезжает в другую половину переписи.
        clean = ('{"item":[{"name":"s","request":{"url":{"raw":"{{ownRestBaseUrl}}/x"}}}]}')
        for lane, runs, expect in (("declared", ["own-only"], 1), ("removed", [], 0)):
            base = tmp / f"pipeline-{lane}"
            t6 = _mk(base, {"own-only": clean},
                     {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = _st_run(t6, workflows=_wf(base, runs=runs))
            out = buf.getvalue()
            _c(f"шаг прогона {'объявлен' if runs else 'СНЯТ'} — гоняется {expect}",
               f"гоняется здесь:    {expect}" in out, out[:500])
            if not runs:
                _c("и причина названа отсутствием шага конвейера",
                   "ни один шаг конвейера" in out, out[:700])

        # Ось 6б: `--service` В КОММЕНТАРИИ не считается шагом. Разбор читает
        # разобранный YAML; проверка по подстроке краснела бы на объяснении.
        base = tmp / "pipeline-comment"
        t6b = _mk(base, {"own-only": clean},
                  {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        wf = _wf(base, runs=[])
        (wf / "e2e-newman.yml").write_text(
            "name: proof\non: [push]\njobs:\n  stand:\n    steps:\n"
            "      # ./scripts/run.sh --service own-only  (когда-то гонялось здесь)\n"
            "      - run: echo нечего\n", encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t6b, workflows=wf)
        out = buf.getvalue()
        _c("`--service` только в комментарии — НЕ шаг прогона",
           "гоняется здесь:    0" in out, out[:500])

        # ── Ось 6г: ВНУТРИ ТЕЛА `run:` ПРОГОН — ЭТО КОМАНДА, А НЕ ТЕКСТ ─────
        #
        # Ось 6б держит комментарий ВНЕ тела шага; эта — внутри. Флаг в
        # комментарии тела, в строковом литерале, в аргументах чужой команды и в
        # данных heredoc — не прогон: шаг, которому оставили только такое
        # упоминание, коллекцию не гоняет, и перепись обязана потребовать у неё
        # держателя. Пара у каждой формы — та же строка КОМАНДОЙ прогонщика, в
        # том числе в формах, которыми дерево её пишет (продолжение строки и
        # `|| rc=$?` у шага chart-own). Каждая форма судится обоими признаками:
        # ответом разборщика и половиной переписи.
        def _wf_body(base: pathlib.Path, body: str,
                     shell: str | None = None) -> pathlib.Path:
            wfb = base / ".github" / "workflows"
            wfb.mkdir(parents=True, exist_ok=True)
            block = "".join(f"          {ln}\n" if ln else "\n"
                            for ln in body.split("\n"))
            (wfb / "e2e-newman.yml").write_text(
                "name: proof\non: [push]\njobs:\n  stand:\n    steps:\n"
                "      - name: шаг с упоминанием прогонщика\n"
                + (f"        shell: {shell}\n" if shell else "")
                + "        run: |\n" + block, encoding="utf-8")
            return wfb

        body_forms = (
            ("комментарий тела", False,
             "cd tests/newman\n# снято до #999: ./scripts/run.sh --service own-only"),
            ("хвост-комментарий после команды", False,
             "cd tests/newman\ntrue  # ./scripts/run.sh --service own-only"),
            # Комментарий с разделителем команд: без разбора комментария `;`
            # отделил бы упоминание в самостоятельную команду.
            ("комментарий тела с разделителем команд", False,
             "cd tests/newman\n# снято до #999; ./scripts/run.sh --service own-only"),
            ("литерал echo в кавычках", False,
             'cd tests/newman\necho "снято: ./scripts/run.sh --service own-only"'),
            ("аргументы echo без кавычек", False,
             "cd tests/newman\necho снято: ./scripts/run.sh --service own-only"),
            ("литерал аргумента чужой команды", False,
             "printf '%s\\n' './scripts/run.sh --service own-only'"),
            ("данные heredoc", False,
             "cat <<'NOTE'\n./scripts/run.sh --service own-only\nNOTE"),
            ("та же строка командой", True,
             "cd tests/newman\n./scripts/run.sh --service own-only"),
            ("командой с продолжением строки и `|| rc=$?`", True,
             "cd tests/newman\nrc=0\n./scripts/run.sh \\\n  --service own-only \\\n"
             '  --ssl-client-cert "$W/edge.crt" || rc=$?'),
            # Продолжение строки посреди слова снимается целиком, как у bash:
            # имя коллекции склеивается, а не рвётся на два слова.
            ("командой с продолжением строки посреди имени", True,
             "./scripts/run.sh --service own-\\\nonly"),
            ("командой в условии if", True,
             "if ./scripts/run.sh --service own-only; then echo ok; fi"),
            ("командой внутри подстановки в кавычках", True,
             'out="$(./scripts/run.sh --service own-only)"'),
            # Апостроф в комментарии кавычки не открывает: иначе она проглотила
            # бы команду ниже, и настоящий прогон выпал бы из счёта.
            ("командой после комментария с апострофом", True,
             "# it's the recovery lane\n./scripts/run.sh --service own-only"),
            ("командой после heredoc", True,
             "cat <<'NOTE'\nничего\nNOTE\n./scripts/run.sh --service own-only"),
            ("командой через bash -c", True,
             "bash -c './scripts/run.sh --service own-only'"),
        )
        for k, (label, runs_it, body) in enumerate(body_forms):
            base = tmp / f"pipeline-body-{k}"
            t6g = _mk(base, {"own-only": clean},
                      {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
            wfb = _wf_body(base, body)
            parsed = pipeline_runs(wfb)
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t6g, workflows=wfb)
            out = buf.getvalue()
            want = 1 if runs_it else 0
            _c(f"`--service` в теле `run:` — {label}: "
               f"{'ПРОГОН' if runs_it else 'НЕ прогон'}",
               bool(parsed.get("own-only")) == runs_it
               and f"гоняется здесь:    {want}" in out,
               f"разборщик: {parsed}; перепись: {out[:300]}")

        # Ось 6д: тело шага с ИНОЙ оболочкой — не программа bash, и её строка,
        # похожая на команду прогонщика, прогоном не засчитывается. Близнец —
        # то же тело под `shell: bash`: различие ровно в оболочке шага.
        same = "./scripts/run.sh --service own-only"
        for k, (shell, runs_it) in enumerate((("python {0}", False),
                                              ("bash {0}", True))):
            base = tmp / f"pipeline-shell-{k}"
            wfb = _wf_body(base, same, shell=shell)
            parsed = pipeline_runs(wfb)
            _c(f"та же строка под `shell: {shell}` — "
               f"{'ПРОГОН' if runs_it else 'НЕ прогон'}",
               bool(parsed.get("own-only")) == runs_it, f"разборщик: {parsed}")

        # Ось 6е (kaname#848): шаг гоняет коллекции по ПЛАНУ ШАРДОВ — литерал
        # `--shard-plan` засчитывает все наборы плана тем же разбором, что у
        # прогонщика. Близнецы: план без коллекции — не прогон её; план в
        # комментарии — не прогон; план, который не читается, — третий исход.
        plan_forms = (
            ("план называет коллекцию", "x: own-only\n", True,
             './scripts/run.sh --shard-plan plan.txt --shard "$S"'),
            ("план её не называет", "x: other\n", False,
             './scripts/run.sh --shard-plan plan.txt --shard "$S"'),
            ("план только в комментарии", "x: own-only\n", False,
             '# ./scripts/run.sh --shard-plan plan.txt --shard "$S"'),
        )
        for k, (label, plan_text, runs_it, body) in enumerate(plan_forms):
            base = tmp / f"pipeline-plan-{k}"
            nm = _mk(base, {"own-only": clean},
                     {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
            (nm / "plan.txt").write_text(plan_text, encoding="utf-8")
            parsed = pipeline_runs(_wf_body(base, "cd tests/newman\n" + body))
            _c(f"`--shard-plan` в теле `run:` — {label}: "
               f"{'ПРОГОН' if runs_it else 'НЕ прогон'}",
               bool(parsed.get("own-only")) == runs_it, f"разборщик: {parsed}")
        base = tmp / "pipeline-plan-unreadable"
        _mk(base, {"own-only": clean}, {"runId": ""})
        try:
            pipeline_runs(_wf_body(base, './scripts/run.sh --shard-plan absent.txt --shard x'))
            unmet = False
        except Unmet:
            unmet = True
        _c("план шардов не читается — третий исход, а не «шаг ничего не гоняет»", unmet)

        # Ось 6в: объявлений конвейера НЕТ — третий исход, а не «гоняется 0».
        base = tmp / "pipeline-absent"
        t6c = _mk(base, {"own-only": clean},
                  {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = _st_run(t6c, workflows=base / "нет-такого-каталога")
        _c("каталога объявлений нет — код 75, а НЕ 0 и не 1", rc == 75,
           buf.getvalue()[-300:])
        _c("и текст называет несозданное условие",
           "УСЛОВИЕ НЕ СОЗДАНО" in buf.getvalue(), buf.getvalue()[-300:])

        # ── Ось 7: ПРИРОДА КЛЮЧА РАЗЛИЧАЕТСЯ, И «ЧЕЛОВЕК» НЕ ЗОВЁТ МАШИНУ ───
        #
        # ЗАМЕР, А НЕ ИМЯ. `humanAccCrudUserId` читается кейсом как идентификатор
        # ТОГО ЖЕ вызывающего, чей предъявитель — `jwtHumanAccCrud`: утверждение
        # кейса — «ownerUserId == caller», и образец требует префикса `usr`.
        # Значит ключ производит ЦЕРЕМОНИЯ, а машинный посев не производит его ни
        # при каком устройстве: служебная учётка человеком не является, её
        # идентификатор несёт префикс `sva`, и подставленное значение дало бы
        # кейс, проверивший подстановку.
        #
        # ЦЕНА ПРЕЖНЕГО УЧЁТА НАЗВАНА: строка долга звала читателя завести
        # машинный посев тому, чего машинный посев не производит, — то есть
        # ОБЪЯВЛЯЛА возможность, неисполнимую by construction.
        #
        # ЗАКОННЫЙ БЛИЗНЕЦ РЯДОМ и отличается ОДНИМ фактом: `svaInviteeId` —
        # идентификатор СЛУЖЕБНОЙ учётки (кейсы читают его при
        # `subjectType=service_account`), и он обязан остаться машинным.
        for lane, key, want_ceremony in (("human-id", "humanAccCrudUserId", True),
                                         ("machine-id", "svaInviteeId", False)):
            base = tmp / f"nature-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{baseUrl}}/iam/v1/x"}},'
                    '"event":[{"listen":"test","script":{"exec":['
                    f'"pm.environment.get(\'{key}\')"]}}}}]}}]}}')
            t7 = _mk(base, {"nature": body},
                     {"baseUrl": "http://edge", key: "", "runId": ""})
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t7, workflows=_wf(base, runs=["nature"]))
            out = buf.getvalue()
            # СУДИТСЯ ГОЛОВА ПРЕПЯТСТВИЯ, А НЕ ПОДСТРОКА ВЫВОДА, и это не
            # педантизм: первая редакция этой оси искала «машинный посев» по
            # всему выводу и краснела на СОБСТВЕННОМ объяснении препятствия
            # церемонии («…машинный посев не производит ни одного»). Тот самый
            # класс, который шапка `pipeline_runs` называет про грепанье
            # комментариев, применённый не к конвейеру, а к самой переписи.
            _c(f"{key}: препятствие названо "
               f"{'ЦЕРЕМОНИЕЙ ЧЕЛОВЕКА' if want_ceremony else 'машинным посевом'}",
               ("нужна ЦЕРЕМОНИЯ ЧЕЛОВЕКА" in out) == want_ceremony
               and ("нужен машинный посев поверхности" in out) != want_ceremony,
               out[:900])

        # ── Ось 7б: ПОВЫШЕННЫЙ УРОВЕНЬ НАСЛЕДУЕТ ПРИРОДУ ПРЕДЪЯВИТЕЛЯ ───────
        #
        # Уровень — свойство сессии входа, и у человека его поднимает только
        # церемония (вход вторым фактором). У машины уровня нет: общее правило
        # повышения освобождает машинного принципала первой ветвью, и слот
        # повышенного уровня машинного распорядителя — ТОТ ЖЕ принципал (кейсы
        # выпускают под `jwtAccountAdminAStepUp` и опрашивают под
        # `jwtAccountAdminA`). Прежняя редакция объявляла церемонией ЛЮБОЙ
        # `*StepUp` и опиралась на шапку, пересказывавшую опровергнутую запись
        # платформы (kaname#398).
        #
        # ТРИ ПОЛОСЫ, КАЖДАЯ МЕНЯЕТ ОДИН ФАКТ: человек повышенного уровня —
        # церемония; машина повышенного уровня — машинный посев; та же машина без
        # суффикса — машинный посев (законный близнец второй полосы).
        for lane, key, want_ceremony in (("human-stepup", "jwtHumanCeremonyStepUp", True),
                                         ("machine-stepup", "jwtAccountAdminAStepUp", False),
                                         ("plain", "jwtAccountAdminA", False)):
            base = tmp / f"stepup-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{baseUrl}}/iam/v1/x"}},'
                    '"event":[{"listen":"test","script":{"exec":['
                    f'"pm.environment.get(\'{key}\')"]}}}}]}}]}}')
            t7b = _mk(base, {"stepup": body},
                      {"baseUrl": "http://edge", key: "", "runId": ""})
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t7b, workflows=_wf(base, runs=["stepup"]))
            out = buf.getvalue()
            _c(f"{key}: препятствие названо "
               f"{'ЦЕРЕМОНИЕЙ ЧЕЛОВЕКА' if want_ceremony else 'машинным посевом'}",
               ("нужна ЦЕРЕМОНИЯ ЧЕЛОВЕКА" in out) == want_ceremony
               and ("нужен машинный посев поверхности" in out) != want_ceremony,
               out[:900])

        # ── Ось 7в: КЛЮЧ ЦЕРЕМОНИИ СНИМАЕТ ПОСЕВ СВОЕЙ ПОВЕРХНОСТИ, И ТОЛЬКО ОН ─
        #
        # Посев церемонии (`seed_ceremony.py`) куёт предъявителя человека на
        # собственном фронте службы; коллекция того же фронта, его читающая,
        # препятствия «нужна церемония» больше не несёт (kaname#398). Та же
        # коллекция при посеве, объявившем ДРУГУЮ поверхность, препятствие
        # сохраняет: предъявитель через стенды не переносится.
        for lane, surface_decl, lifted in (
                ("own", "служба (собственный REST-фронт)", True),
                ("foreign", SURFACE_EDGE, False)):
            base = tmp / f"ceremony-credit-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{baseUrl}}/iam/v1/x"}},'
                    '"event":[{"listen":"prerequest","script":{"exec":['
                    '"pm.environment.get(\'ownRestBaseUrl\')",'
                    '"pm.environment.get(\'jwtHumanCeremony\')"]}}]}]}')
            t7c = _mk(base, {"cer": body},
                      {"baseUrl": "http://edge", "ownRestBaseUrl": "https://own",
                       "jwtHumanCeremony": "", "runId": ""})
            fx = t7c.parent / "authz-fixtures"
            fx.mkdir(parents=True, exist_ok=True)
            (fx / "seed_ceremony.py").write_text(
                "import sys\n"
                "if '--minted-keys' in sys.argv:\n"
                "    print('jwtHumanCeremony')\n"
                "elif '--minted-surface' in sys.argv:\n"
                f"    print({surface_decl!r})\n",
                encoding="utf-8")
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t7c, workflows=_wf(base, runs=["cer"]))
            out = buf.getvalue()
            _c(f"ключ церемонии, посев поверхности «{surface_decl}»: препятствие "
               f"{'снято' if lifted else 'ОСТАЛОСЬ'}",
               ("нужна ЦЕРЕМОНИЯ ЧЕЛОВЕКА" in out) != lifted, out[:900])

        # ── Ось 8: АДРЕС — НЕ ПОСЕВ, И ЕГО ПРОИЗВОДИТ СТЕНД ──────────────────
        #
        # Тот же класс, что уже назван в шапке `blockers`: из шести пустых ключей
        # своей поверхности два были АДРЕСАМИ, и прежняя редакция звала их
        # удостоверениями. Ключи `iamJwksBaseUrl` и `providerPublicBaseUrl` — того
        # же рода: их не выпускает ни один подписант, их НАЗЫВАЕТ посадка.
        # Законный близнец — предъявитель той же коллекции: он обязан остаться
        # машинным посевом.
        for lane, key, want_address in (("addr", "iamJwksBaseUrl", True),
                                        ("cred", "jwtBootstrap", False)):
            base = tmp / f"addrnature-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{baseUrl}}/iam/v1/x"}},'
                    '"event":[{"listen":"test","script":{"exec":['
                    f'"pm.environment.get(\'{key}\')"]}}}}]}}]}}')
            t8 = _mk(base, {"nature": body},
                     {"baseUrl": "http://edge", key: "", "runId": ""})
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t8, workflows=_wf(base, runs=["nature"]))
            out = buf.getvalue()
            _c(f"{key}: препятствие названо "
               f"{'АДРЕСОМ' if want_address else 'машинным посевом'}",
               ("нужен АДРЕС поверхности" in out) == want_address
               and ("нужен машинный посев поверхности" in out) != want_address,
               out[:900])

        # ── Ось 9: СТРОКА ДОЛГА НАЗЫВАЕТ ПОВЕРХНОСТЬ, ЧЕЙ ПОСЕВ ТРЕБУЕТСЯ ────
        #
        # ЦЕНА ИЗМЕРЕНА И ОНА — ПЛАН ЦЕЛОЙ ПОЛОСЫ. Учёт поклюсевой и по
        # поверхности стоит здесь с самого начала (оси 3б и 3г), а вот СТРОКА про
        # него молчала: она говорила «которых не пишет ни один посев ЭТОЙ
        # поверхности», не называя, КАКОЙ. Читатель печатного долга видел 39
        # коллекций с препятствием «нужен машинный посев» и заводил полосу
        # «расширить посев» — при том что все 39 суть коллекции КРАЯ, и посев
        # собственного фронта им не зачитывается НИ ОДНИМ ключом by construction.
        # То есть число, на которое ставился план, сдвинуть было нечем.
        #
        # Инъекция: коллекция КРАЯ и посев СВОЕЙ поверхности в одном дереве.
        # Строка обязана назвать ЯРЛЫК АДРЕСАЦИИ края — поверхность, чьего посева
        # нет, — а не поверхность посева, который в дереве лежит. Ярлык берётся
        # КОНСТАНТОЙ: повтори его текстом, и переименование оставило бы эту ось
        # зелёной на прежнем слове.
        base = tmp / "surface-named"
        edge_seeded = ('{"item":[{"name":"s","request":{"url":{"raw":'
                       '"{{baseUrl}}/iam/v1/x"}},'
                       '"event":[{"listen":"test","script":{"exec":['
                       '"pm.environment.get(\'jwtAccountAdminA\')"]}}]}]}')
        t9 = _mk(base, {"edge-seeded": edge_seeded},
                 {"baseUrl": "http://edge", "jwtAccountAdminA": "", "runId": ""})
        fx9 = t9.parent / "authz-fixtures"
        fx9.mkdir(parents=True, exist_ok=True)
        (fx9 / "seed_probe.py").write_text(
            "import sys\n"
            "if '--minted-keys' in sys.argv:\n"
            "    print('jwtAccountAdminA')\n"
            "elif '--minted-surface' in sys.argv:\n"
            "    print('служба (собственный REST-фронт)')\n",
            encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t9, workflows=_wf(base, runs=["edge-seeded"]))
        out = buf.getvalue()
        _c("строка машинного посева НАЗЫВАЕТ поверхность, чей посев требуется",
           f"машинный посев поверхности «{SURFACE_EDGE}»" in out, out[:800])
        _c("и НЕ называет поверхность посева, который в дереве лежит",
           "машинный посев поверхности «служба" not in out, out[:800])

        # ── Ось 12: НЕПОСЕЯННЫЙ КЛЮЧ С ЧУЖИМ ЛИТЕРАЛОМ ──────────────────────
        #
        # ПУСТОЙ КЛЮЧ — НЕ ЕДИНСТВЕННОЕ СОСТОЯНИЕ НЕПОСЕЯННОГО. Шаблон несёт
        # `userNOBId`, `userAAAId`, `projectB1Id` НЕПУСТЫМИ — правдоподобными
        # `usr…`/`prj…` чужого стенда. Посев автономного стенда их не куёт, значит
        # на нём они указывают в пустоту, а перепись их НЕ ВИДЕЛА: предикат
        # спрашивал только про пустое значение.
        #
        # ЦЕНА РАЗНАЯ, И ПОТОМУ ВИД НАЗЫВАЕТСЯ ОТДЕЛЬНО. Пустой ключ падает
        # ГРОМКО — страж набора утверждает его по имени до первого запроса.
        # Литерал чужого стенда доезжает до службы и возвращается 403/404, то есть
        # ПОХОЖИМ НА ДЕФЕКТ ПРОДУКТА.
        #
        # Законных близнеца ДВА, и каждый отличается одним фактом: тот же литерал,
        # но посев его КУЁТ — препятствия нет; и АДРЕС с непустым литералом — его
        # поверхность названа отдельной строкой, второй раз он не считается.
        for lane, minted_key, want in (("unminted", "jwtSomethingElse", True),
                                       ("minted", "userNOBId", False)):
            base = tmp / f"literal-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{ownRestBaseUrl}}/x"}},'
                    '"event":[{"listen":"test","script":{"exec":['
                    '"pm.environment.get(\'userNOBId\')"]}}]}]}')
            t12 = _mk(base, {"literal": body},
                      {"ownRestBaseUrl": "https://localhost:9098",
                       "userNOBId": "usry4tz0kfahkv1favw1", "runId": ""})
            fx = t12.parent / "authz-fixtures"
            fx.mkdir(parents=True, exist_ok=True)
            (fx / "seed_probe.py").write_text(
                "import sys\n"
                "if '--minted-keys' in sys.argv:\n"
                f"    print({minted_key!r})\n"
                "elif '--minted-surface' in sys.argv:\n"
                "    print('служба (собственный REST-фронт)')\n",
                encoding="utf-8")
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t12, workflows=_wf(base, runs=["literal"]))
            out = buf.getvalue()
            _c(f"непустой `userNOBId`, посев его {'НЕ куёт' if want else 'куёт'} — "
               f"препятствие {'названо' if want else 'снято'}",
               (f"НЕ гоняется здесь: {1 if want else 0}" in out
                and f"{KEY_STATE_LITERAL}: {1 if want else 0}" in out), out[:900])

        # Законный близнец про АДРЕС: непустое значение переменной края вторым
        # препятствием не считается — его поверхность уже названа своей строкой.
        base = tmp / "literal-address"
        edge_plain = ('{"item":[{"name":"s","request":{"url":{"raw":'
                      '"{{baseUrl}}/iam/v1/x"}}}]}')
        t12b = _mk(base, {"edge-plain": edge_plain},
                   {"baseUrl": "http://localhost:18080", "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t12b, workflows=_wf(base, runs=["edge-plain"]))
        out = buf.getvalue()
        _c("непустой АДРЕС края литералом чужого стенда НЕ называется",
           f"{KEY_STATE_LITERAL}: 0" in out, out[:900])
        _c("и его поверхность названа своей строкой",
           "адресуется к краю платформы (переменная базового адреса)" in out,
           out[:900])

        # ── Ось 13: КЛЮЧА НЕТ В ШАБЛОНЕ ВОВСЕ ───────────────────────────────
        #
        # Третье состояние непосеянного: ключ читается, а строки под него в
        # шаблоне НЕТ. Прежний предикат спрашивал `k in empty` и такой ключ не
        # видел by construction — непосеянность выглядела нулём.
        #
        # ЗАКОННЫХ БЛИЗНЕЦА ТРИ, и все три — законные написания того, что
        # коллекция производит САМА (`testing.md` §«Гейт на класс», п. 7):
        # обычные кавычки, ЭКРАНИРОВАННЫЕ кавычки (`set(\"k\"` — так генератор
        # пишет разбор набора ключей) и снятие (`unset('k')` — так снимается
        # временная запись). Ни одно из трёх препятствием не является: стенд
        # такой ключ производить не обязан.
        for lane, extra, want in (
                ("absent", '', True),
                ("self-plain", '","pm.environment.set(\'k13\', \'v\')', False),
                ("self-escaped", '","pm.environment.set(\\"k13\\", \'v\')', False),
                ("self-unset", '","pm.environment.unset(\'k13\')', False)):
            base = tmp / f"absent-{lane}"
            body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                    '"{{ownRestBaseUrl}}/x"}},'
                    '"event":[{"listen":"test","script":{"exec":['
                    '"pm.environment.get(\'k13\')' + extra + '"]}}]}]}')
            t13 = _mk(base, {"absent": body},
                      {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                _st_run(t13, workflows=_wf(base, runs=["absent"]))
            out = buf.getvalue()
            _c(f"ключ вне шаблона, коллекция его "
               f"{'НЕ пишет' if want else f'пишет ({lane})'} — препятствие "
               f"{'названо' if want else 'снято'}",
               (f"НЕ гоняется здесь: {1 if want else 0}" in out
                and f"{KEY_STATE_ABSENT}: {1 if want else 0}" in out), out[:900])

        # ── Ось 14: ПЕРЕПИСЬ ПЕЧАТАЕТ СОСТОЯНИЯ ОТДЕЛЬНО ────────────────────
        #
        # «Оба вида отдельно» — не украшение: читатель, видящий одно число
        # «непосеянных ключей», не отличит громкого отказа стража от тихого
        # 404 по чужому литералу, а чинятся они разным.
        base = tmp / "states"
        body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                '"{{ownRestBaseUrl}}/x"}},'
                '"event":[{"listen":"test","script":{"exec":['
                '"pm.environment.get(\'jwtEmptyOne\')",'
                '"pm.environment.get(\'userNOBId\')",'
                '"pm.environment.get(\'absentOne\')"]}}]}]}')
        t14 = _mk(base, {"states": body},
                  {"ownRestBaseUrl": "https://localhost:9098",
                   "jwtEmptyOne": "", "userNOBId": "usry4tz0kfahkv1favw1",
                   "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t14, workflows=_wf(base, runs=["states"]))
        out = buf.getvalue()
        _c("перепись печатает ТРИ состояния ключа по отдельности",
           all(f"{s}: " in out for s in (KEY_STATE_EMPTY, KEY_STATE_LITERAL,
                                         KEY_STATE_ABSENT)), out[:1200])
        _c("и каждое своим числом",
           f"{KEY_STATE_EMPTY}: 1" in out and f"{KEY_STATE_LITERAL}: 1" in out
           and f"{KEY_STATE_ABSENT}: 1" in out, out[:1200])

        # ── Ось 15: КАТЕГОРИЯ A ПРИ ТРЕБОВАНИИ ЦЕРЕМОНИИ — НАХОДКА ──────────
        #
        # Ведомость сама определяет B как «нужен ЧЕЛОВЕЧЕСКИЙ предъявитель».
        # Запись A у коллекции, читающей предъявителя человека повышенного
        # уровня, объявляет её переводимой машинным посевом — возможность,
        # неисполнимую by construction.
        # Ведомость подаётся ЯВНО, мимо `_st_ledger`: иначе ось судила бы то же
        # правило, которым синтетическая ведомость и строится, то есть себя.
        base = tmp / "misfiled"
        stepup_body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                       '"{{ownRestBaseUrl}}/x"}},'
                       '"event":[{"listen":"test","script":{"exec":['
                       '"pm.environment.get(\'jwtHumanCeremonyStepUp\')"]}}]}]}')
        t15 = _mk(base, {"misfiled": stepup_body},
                  {"ownRestBaseUrl": "https://localhost:9098",
                   "jwtHumanCeremonyStepUp": "", "runId": ""})
        wf15 = _wf(base, runs=["misfiled"])
        err = io.StringIO()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            rc = run(t15, workflows=wf15, ledger={"misfiled": ("A", "довод", "")})
        _c("A при требовании церемонии — код 1", rc == 1, f"код {rc}")
        _c("и находка называет коллекцию и ключ",
           "misfiled" in err.getvalue()
           and "jwtHumanCeremonyStepUp" in err.getvalue(), err.getvalue()[:400])

        # ЗАКОННЫЙ БЛИЗНЕЦ ПЕРВЫЙ: та же коллекция, категория B — молчание.
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            rc = run(t15, workflows=wf15, ledger={"misfiled": ("B", "довод", "")})
        _c("ЗАКОННЫЙ БЛИЗНЕЦ: та же коллекция как B — код 0", rc == 0, f"код {rc}")

        # ЗАКОННЫЙ БЛИЗНЕЦ ВТОРОЙ: категория A у коллекции БЕЗ церемонии —
        # молчание. Без него ось краснела бы на любой записи A.
        base = tmp / "filed-ok"
        plain_body = ('{"item":[{"name":"s","request":{"url":{"raw":'
                      '"{{ownRestBaseUrl}}/x"}},'
                      '"event":[{"listen":"test","script":{"exec":['
                      '"pm.environment.get(\'jwtAccountAdminA\')"]}}]}]}')
        t15b = _mk(base, {"filed-ok": plain_body},
                   {"ownRestBaseUrl": "https://localhost:9098",
                    "jwtAccountAdminA": "", "runId": ""})
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            rc = run(t15b, workflows=_wf(base, runs=["filed-ok"]),
                     ledger={"filed-ok": ("A", "довод", "")})
        _c("ЗАКОННЫЙ БЛИЗНЕЦ: A без церемонии — код 0", rc == 0, f"код {rc}")

        # Ось 4: коллекция края попадает в «не гоняется» с причиной про край.
        edge = ('{"item":[{"name":"s","request":{"url":{"raw":"{{baseUrl}}/iam/v1/x"}}}]}')
        t4 = _mk(tmp / "edge", {"edge-only": edge}, {"baseUrl": "http://x", "runId": ""})
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            _st_run(t4, workflows=_wf(tmp / "edge", runs=["edge-only"]))
        out = buf.getvalue()
        _c("коллекция края — в «НЕ гоняется»", "НЕ гоняется здесь: 1" in out, out[:400])
        _c("и причина названа АДРЕСАЦИЕЙ, а не вердиктом о производителе",
           "адресуется к краю платформы (переменная базового адреса)" in out, out[:400])
        _c("причина НЕ утверждает о производителе",
           "его производитель — чужой стенд" not in out, out[:400])

        # ── Ось 10: ВЕДОМОСТЬ ПРОИЗВОДИТЕЛЯ СВЕРЯЕТСЯ С ДЕРЕВОМ В ОБЕ СТОРОНЫ ─
        #
        # Это тот механизм, которым снят довод против второго списка: «выписанный
        # перечень разошёлся бы с деревом молча». Молча он не разойдётся — он
        # УРОНИТ прогон, и обе стороны расхождения проверяются здесь по одной.
        # Без этой оси ведомость была бы ровно тем, чего опасалась прежняя шапка.
        lt = _mk(tmp / "ledger", {"edge-only": edge},
                 {"baseUrl": "http://x", "runId": ""})
        lwf = _wf(tmp / "ledger", runs=["edge-only"])

        buf = io.StringIO()
        err = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(err):
            rc = run(lt, workflows=lwf, ledger={})
        _c("коллекция БЕЗ записи ведомости роняет перепись", rc == 1, f"код {rc}")
        _c("и находка называет коллекцию",
           "edge-only" in err.getvalue() and "не записано" in err.getvalue(),
           err.getvalue()[:300])

        err = io.StringIO()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            rc = run(lt, workflows=lwf,
                     ledger={"edge-only": ("C", "довод", ""), "ушедшая": ("A", "довод", "")})
        _c("запись БЕЗ коллекции роняет перепись — перечень не переживает предмет",
           rc == 1, f"код {rc}")
        _c("и находка называет запись",
           "ушедшая" in err.getvalue() and "пережила свой предмет" in err.getvalue(),
           err.getvalue()[:300])

        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = run(lt, workflows=lwf, ledger={"edge-only": ("C", "довод", "")})
        _c("ЗАКОННЫЙ БЛИЗНЕЦ: ведомость сходится с деревом — перепись печатается",
           rc == 0, f"код {rc}")

        err = io.StringIO()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            rc = run(lt, workflows=lwf, ledger={"edge-only": ("Z", "довод", "")})
        _c("категория вне закрытого словаря — находка", rc == 1, f"код {rc}")

        err = io.StringIO()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            rc = run(lt, workflows=lwf, ledger={"edge-only": ("C", "   ", "")})
        _c("категория БЕЗ довода — находка: это мнение, а не решение",
           rc == 1, f"код {rc}")

        # ── Ось 11: ДВЕ ВЕЛИЧИНЫ РАЗЛИЧИМЫ, и их расхождение названо числом ──
        #
        # Ярлык адресации и решение о производителе обязаны РАСХОДИТЬСЯ на том
        # самом входе, ради которого ведомость и заведена: коллекция стучится к
        # краю, а утверждения её производит служба. Сойдись они здесь — ведомость
        # ничего не добавляла бы к выводу из адреса.
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            run(lt, workflows=lwf, ledger={"edge-only": ("A", "предмет службы", "")})
        out = buf.getvalue()
        _c("адресация и производитель напечатаны ОБЕ",
           f"адресация: {SURFACE_EDGE}" in out and "производитель: A" in out,
           out[:600])
        _c("расхождение названо ОТДЕЛЬНЫМ числом",
           "адресуется к краю, а производитель — служба: 1" in out, out[:900])

        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            run(lt, workflows=lwf, ledger={"edge-only": ("C", "предмет края", "")})
        _c("ЗАКОННЫЙ БЛИЗНЕЦ: производитель края — расхождения ноль",
           "адресуется к краю, а производитель — служба: 0" in buf.getvalue(),
           buf.getvalue()[:900])

        # Ось 5: ОБЕ величины печатаются всегда — и когда вторая ноль.
        _c("печатаются обе величины, а не только одна",
           "гоняется здесь:" in out and "НЕ гоняется здесь:" in out)

        # ── Ось 16: У НЕГОНЯЕМОЙ КОЛЛЕКЦИИ ЕСТЬ ДЕРЖАТЕЛЬ, У ГОНЯЕМОЙ — НЕТ ─────
        #
        # Производитель коллекции — шаг конвейера, который её гоняет, либо
        # ДЕРЖАТЕЛЬ в ведомости: задача, которая её прогонит. Без третьего поля
        # «не гоняется» было концом записи: причина печаталась, а кто снимет
        # препятствие, не было записано нигде, и долг стоял без читателя.
        #
        # Пара по каждой стороне, различие ровно в одном факте. Сторона первая:
        # коллекция не гоняется, держателя нет — находка; тот же вход с
        # держателем по форме — молчание. Сторона вторая, САМОИСТЕЧЕНИЕ: шаг её
        # гоняет, а держатель записан — запись пережила свой предмет; тот же
        # шаг без держателя — молчание.
        hdir = tmp / "holder"
        held = _mk(hdir, {"edge-only": edge}, {"baseUrl": "http://x", "runId": ""})
        hwf_none = _wf(hdir / "none", runs=[])
        hwf_runs = _wf(hdir / "runs", runs=["edge-only"])
        holder = "PRO-Robotech/kaname#1 — синтетика: прогонит на своём стенде"
        for label, wf16, entry, want_rc, want_text in (
                ("не гоняется, держателя нет — находка",
                 hwf_none, ("C", "довод", ""), 1, "держателя"),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: не гоняется, держатель по форме — молчание",
                 hwf_none, ("C", "довод", holder), 0, ""),
                ("гоняется шагом, а держатель записан — запись пережила предмет",
                 hwf_runs, ("C", "довод", holder), 1, "пережил"),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: гоняется шагом, держателя нет — молчание",
                 hwf_runs, ("C", "довод", ""), 0, ""),
                ("держатель вне закрытой формы — находка",
                 hwf_none, ("C", "довод", "когда-нибудь прогоним"), 1, "форм")):
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(held, workflows=wf16, ledger={"edge-only": entry})
            _c(f"держатель: {label} (код {want_rc})",
               rc == want_rc and (not want_text or (
                   want_text in err.getvalue() and "edge-only" in err.getvalue())),
               f"код {rc}; {err.getvalue()[:300]}")

        # Держатель ПЕЧАТАЕТСЯ рядом с позицией и сводится по задаче: предикат
        # задачи читается выводом переписи, а не прочтением ведомости.
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            run(held, workflows=hwf_none, ledger={"edge-only": ("C", "довод", holder)})
        out16 = buf.getvalue()
        _c("строка позиции называет держателя",
           f"держатель: {holder}" in out16, out16[-900:])
        _c("свод по держателю назван числом",
           "по ДЕРЖАТЕЛЮ" in out16 and "PRO-Robotech/kaname#1: 1" in out16, out16[-900:])
        _c("негоняемые с держателем названы числом",
           "НЕ гоняет ни один шаг: 1 — держатель назван у 1" in out16, out16[-900:])


        # Ось 17: ПОЗИЦИИ ПРИЁМОК УРОВНЯ E (kaname#449). Позиция мельче коллекции:
        # приёмка объявляет сквозным сценарий, и без кейса он не виден ведомости
        # коллекций вовсе. Пара по каждой стороне, различие в одном факте.
        pdir = tmp / "positions"
        pn = _mk(pdir, {"carrier": own}, {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        pwf_runs = _wf(pdir / "runs", runs=["carrier"])
        pwf_none = _wf(pdir / "none", runs=[])
        acc = pdir / ACCEPTANCE_REL
        acc.mkdir(parents=True, exist_ok=True)
        base_heads = ("**ID: SYN-01** · I + E — несётся кейсом\n"
                      "**ID: SYN-02** · I — только интеграция\n"
                      "**ID: SYN-03** · E — не несётся ничем\n"
                      "**ID: SYN-05** · отрицание; близнец — SYN-01, довод словами\n")
        (pn / "cases").mkdir(parents=True, exist_ok=True)
        (pn / "cases" / "carrier.py").write_text(
            '"""Модуль кейсов: несёт SYN-01."""\n# SYN-03 здесь только комментарием\nCASES = []\n',
            encoding="utf-8")
        hold = "PRO-Robotech/kaname#1 — синтетика: заведёт кейс"
        pled = {"carrier": ("A", "довод", "")}
        for label, debt, extra, want_rc, want_text in (
                ("позиция E без кейса и без записи — находка; комментарий кейсом не считается",
                 {}, "", 1, "позиция SYN-03"),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: та же позиция записана долгом по форме — молчание",
                 {"SYN-03": ("довод", hold)}, "", 0, ""),
                ("запись долга позиции, которую несёт модуль, — пережила предмет",
                 {"SYN-03": ("довод", hold), "SYN-01": ("довод", hold)}, "", 1, "несёт модуль carrier"),
                ("запись долга позиции без уровня E — без предмета",
                 {"SYN-03": ("довод", hold), "SYN-02": ("довод", hold)}, "", 1, "нет ни в одной приёмке"),
                ("держатель позиции вне закрытой формы — находка",
                 {"SYN-03": ("довод", "когда-нибудь")}, "", 1, "вне закрытой формы"),
                ("перечень уровней в незнакомой форме — находка, а не пропуск",
                 {"SYN-03": ("довод", hold)}, "**ID: SYN-04** · I+E — слитно\n", 1, "незнакомой форме")):
            (acc / "synthetic.md").write_text(base_heads + extra, encoding="utf-8")
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(pn, workflows=pwf_runs, ledger=pled, scenario_debt=debt)
            _c(f"позиции: {label} (код {want_rc})",
               rc == want_rc and (not want_text or want_text in err.getvalue()),
               f"код {rc}; {err.getvalue()[:400]}")
        (acc / "synthetic.md").write_text(base_heads, encoding="utf-8")
        for label, wf17, led17, want in (
                ("модуль гоняется шагом", pwf_runs, pled,
                 "позиций 2 — гоняется 1 · собрана, коллекция не гоняется 0 · долг 1"),
                ("модуль собран, коллекцию не гоняет ни один шаг", pwf_none,
                 {"carrier": ("A", "довод", hold)},
                 "позиций 2 — гоняется 0 · собрана, коллекция не гоняется 1 · долг 1")):
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                rc = run(pn, workflows=wf17, ledger=led17, scenario_debt={"SYN-03": ("довод", hold)})
            _c(f"позиции: перепись числом — {label}", rc == 0 and want in buf.getvalue(),
               f"код {rc}; {buf.getvalue()[-700:]}")

        # Ось 18: ВСЕ ЗАКОННЫЕ ФОРМЫ ЗАГОЛОВКА СЦЕНАРИЯ (kaname#449, опыт J4).
        # Приёмки пишут уровни тремя формами, выведенными обходом каталога: ID-префикс
        # `**ID: X** · I + E — …`, жирный ID с заголовком `**X — …** · E + I` (уровни
        # в конце строки, за ними бывает хвост) и уровни в скобках `**X (I).**`.
        # Распознаватель, знающий одну, молчит о двух других: позиция E второй формы
        # без кейса давала код 0. Пара по каждой форме, различие в одном факте.
        fdir = tmp / "forms"
        fn = _mk(fdir, {"carrier": own}, {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        fwf = _wf(fdir / "runs", runs=["carrier"])
        facc = fdir / ACCEPTANCE_REL
        facc.mkdir(parents=True, exist_ok=True)
        fheads = ("**ID: SYN-01** · I + E — форма ID-префикса\n"
                  "**SYN-11 — несётся кейсом** · E + I\n"
                  "**SYN-12 — не несётся ничем** · E\n"
                  "**SYN-13 — хвост после уровней** · E · *новый, редакция 3*\n"
                  "**SYN-14 — перечень через точку** · I · P\n"
                  "**SYN-15 — ссылка в хвосте** · I (→ **SYN-12**)\n"
                  "**SYN-16 — довод словами, уровней нет** (`kacho#1`)\n"
                  "**SYN-21 (E).** Given стенд.\n"
                  "**SYN-22 (I, управляемые часы).** Given контейнер.\n"
                  "**SYN-23 (U).** Given модуль.\n"
                  "**SYN-24 (RED)** пометка, а не уровни\n")
        (fn / "cases").mkdir(parents=True, exist_ok=True)
        (fn / "cases" / "carrier.py").write_text(
            '"""Модуль кейсов: несёт SYN-11."""\nCASES = []\n', encoding="utf-8")
        ftwin = {s: ("довод", hold) for s in ("SYN-01", "SYN-12", "SYN-13", "SYN-21")}

        def _less(sid):
            return {k: v for k, v in ftwin.items() if k != sid}

        for label, debt, extra, want_rc, want_texts in (
                ("вторая форма: позиция E без кейса и без записи — находка",
                 _less("SYN-12"), "", 1, ("позиция SYN-12",)),
                ("вторая форма: уровни с хвостом за ними — позиция E",
                 _less("SYN-13"), "", 1, ("позиция SYN-13",)),
                ("третья форма: уровни в скобках — позиция E",
                 _less("SYN-21"), "", 1, ("позиция SYN-21",)),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: позиции трёх форм записаны либо несутся — молчание",
                 ftwin, "", 0, ()),
                ("вторая форма: запись долга позиции, которую несёт модуль, — пережила предмет",
                 {**ftwin, "SYN-11": ("довод", hold)}, "", 1, ("несёт модуль carrier",)),
                ("вторая форма: запись долга позиции без уровня E — без предмета",
                 {**ftwin, "SYN-14": ("довод", hold)}, "", 1,
                 ("позиции SYN-14", "нет ни в одной приёмке")),
                ("вторая форма: слитный перечень уровней — незнакомая форма",
                 ftwin, "**SYN-17 — слитно** · E+I\n", 1, ("незнакомой форме", "SYN-17")),
                ("вторая форма: буква вне словаря уровней — незнакомая форма",
                 ftwin, "**SYN-18 — буква вне словаря** · X\n", 1, ("незнакомой форме", "SYN-18")),
                ("вторая форма: уровень за незнакомым разделителем — незнакомая форма, а не "
                 "потерянный E", ftwin, "**SYN-19 — косая черта** · I / E\n", 1,
                 ("незнакомой форме", "SYN-19")),
                ("третья форма: слитный перечень в скобках — незнакомая форма",
                 ftwin, "**SYN-25 (E+I).** Given\n", 1, ("незнакомой форме", "SYN-25")),
                ("третья форма: уровень в примечании скобок — незнакомая форма",
                 ftwin, "**SYN-26 (I, E).** Given\n", 1, ("незнакомой форме", "SYN-26")),
                ("первая форма: буква вне словаря уровней — незнакомая форма",
                 ftwin, "**ID: SYN-02** · X — буква вне словаря\n", 1,
                 ("незнакомой форме", "SYN-02")),
                # Уровень K — снаружи через край платформы (легенда приёмки
                # account-id-may-be-supplied-at-create, kaname#549). Он сквозной, как E:
                # позиция K без кейса и без записи — находка, а не молчание; записанная
                # долгом — законный близнец. Различие в одном факте — записи долга.
                ("вторая форма: позиция K без кейса и без записи — находка, а не незнакомая форма",
                 ftwin, "**SYN-31 — через край** · K\n", 1, ("позиция SYN-31",)),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: та же позиция K записана долгом — молчание",
                 {**ftwin, "SYN-31": ("довод", hold)}, "**SYN-31 — через край** · K\n", 0, ()),
                ("вторая форма: K вторым в перечне — позиция",
                 ftwin, "**SYN-32 — интеграция и край** · I + K\n", 1, ("позиция SYN-32",)),
                ("вторая форма: буква вне словаря ВТОРОЙ за знакомым разделителем — "
                 "незнакомая форма, а не молчание", ftwin,
                 "**SYN-35 — вторая буква вне словаря** · I + X\n", 1,
                 ("незнакомой форме", "SYN-35")),
                ("первая форма: позиция K без записи — находка",
                 ftwin, "**ID: SYN-34** · K — через край\n", 1, ("позиция SYN-34",)),
                ("третья форма: позиция K без записи — находка",
                 ftwin, "**SYN-33 (K).** Given край\n", 1, ("позиция SYN-33",)),
                # kaname#903: «несёт перечень» у скобки судится формой УРОВНЯ, а не ID.
                # «(S6)» — не уровень: молчание при любом слове перед скобкой. Близнец
                # отличается одним фактом — уровнем в скобке: «(E)» за прозой —
                # незнакомая форма, за ID любой формы — позиция, а не тишина.
                ("третья форма: проза перед скобкой без уровня — не заголовок, молчание",
                 ftwin, "**Сейчас (S6):** перечень закрыт\n", 0, ()),
                ("третья форма: ID перед скобкой без уровня — перечня нет, молчание",
                 ftwin, "**SYN-36 (S6):** перечень закрыт\n", 0, ()),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: проза перед скобкой С уровнем — незнакомая форма",
                 ftwin, "**Сейчас (E):** перечень закрыт\n", 1, ("незнакомой форме", "Сейчас")),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: ID и уровень в скобках — разобран в позицию",
                 ftwin, "**SYN-37 (E).** перечень закрыт\n", 1, ("позиция SYN-37",)),
                *((f"третья форма: ID вне переписи «{sid}» с уровнем — позиция, а не тишина",
                   ftwin, f"**{sid} (E).** Given край\n", 1, (f"позиция {sid}",))
                  for sid in ("SYN36", "syn-36", "SYN_36", "SYN.36", "SYN-36a"))):
            (facc / "synthetic.md").write_text(fheads + extra, encoding="utf-8")
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(fn, workflows=fwf, ledger=pled, scenario_debt=debt)
            _c(f"формы заголовка: {label} (код {want_rc})",
               rc == want_rc and all(w in err.getvalue() for w in want_texts),
               f"код {rc}; {err.getvalue()[:500]}")
        (facc / "synthetic.md").write_text(fheads, encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = run(fn, workflows=fwf, ledger=pled, scenario_debt=ftwin)
        fout = buf.getvalue()
        _c("формы заголовка: перепись позиций числом по трём формам",
           rc == 0 and "позиций 5 — гоняется 1 · собрана, коллекция не гоняется 0 · долг 4" in fout,
           f"код {rc}; {fout[-900:]}")
        _c("формы заголовка: прочитанное и уровня E названы числом по каждой форме",
           "«**ID: <ID>** · <уровни> — …» 1 · 1; «**<ID> — <заголовок>** · <уровни>» 5 · 3; "
           "«**<ID> (<уровни>).**» 3 · 1" in fout, fout[-900:])

        # Ось 19: ПОЛОСА, НАЗВАННАЯ ДЕРЖАТЕЛЕМ, ЕСТЬ У МОДУЛЯ КЕЙСОВ (kaname#361).
        # Держатель переутверждал полосу IBT-12, снятую вместе с зеркалом набора
        # ключей: модуль сказал это докстрокой, ведомость — нет. Пара по каждому
        # исходу, различие в одном факте против близнеца: названа живая полоса —
        # молчание; снятая (она стоит только докстрокой) либо стоящая только
        # комментарием — находка; полоса чужого семейства не судится; модуль без
        # единого `id=` — находка о слепоте, а не молчание.
        ldir = tmp / "lanes"
        ln = _mk(ldir, {"carrier": own}, {"ownRestBaseUrl": "https://localhost:9098", "runId": ""})
        lwf = _wf(ldir / "none", runs=[])
        (ln / "cases").mkdir(parents=True, exist_ok=True)
        live_mod = ('"""Модуль кейсов. SYN-02 — СНЯТА вместе с предметом."""\n'
                    '# SYN-04 здесь только комментарием\n'
                    'CASES = [Case(id="SYN-01-LIVE"), Case(id="SYN-03-LIVE")]\n')
        blind_mod = 'CASES = [Case(name="SYN-01-LIVE")]\n'
        lhold = "PRO-Robotech/kaname#1 — синтетика: переутвердит полосы "
        for label, mod, holder, want_rc, want_texts in (
                ("ЗАКОННЫЙ БЛИЗНЕЦ: названы живые полосы модуля — молчание",
                 live_mod, lhold + "SYN-01 и SYN-03", 0, ()),
                ("названа полоса, которую модуль называет только докстрокой, — находка",
                 live_mod, lhold + "SYN-01 и SYN-02", 1, ("полосу SYN-02", "carrier")),
                ("названа полоса, стоящая только комментарием, — находка",
                 live_mod, lhold + "SYN-01 и SYN-04", 1, ("полосу SYN-04",)),
                ("полоса чужого семейства не судится — молчание",
                 live_mod, lhold + "SYN-01 и OTHER-07", 0, ()),
                ("модуль без единого id= при названной полосе — находка, а не молчание",
                 blind_mod, lhold + "SYN-01", 1, ("не дал ни одного `id=`",))):
            (ln / "cases" / "carrier.py").write_text(mod, encoding="utf-8")
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(ln, workflows=lwf, ledger={"carrier": ("A", "довод", holder)})
            _c(f"полосы держателя: {label} (код {want_rc})",
               rc == want_rc and all(w in err.getvalue() for w in want_texts),
               f"код {rc}; {err.getvalue()[:400]}")
        (ln / "cases" / "carrier.py").write_text(live_mod, encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = run(ln, workflows=lwf,
                     ledger={"carrier": ("A", "довод", lhold + "SYN-01 и OTHER-07")})
        _c("полосы держателя: перепись называет прочитанное, названное и судимое",
           rc == 0 and ("держателей прочитано 1 · полос названо 2 · из них судимо модулем "
                        "кейсов 1") in buf.getvalue(), f"код {rc}; {buf.getvalue()[-900:]}")

        # Ось 20: ПОЗИЦИЯ, ЧЕЙ СКВОЗНОЙ ДОМ — ДРУГОЙ РЕПОЗИТОРИЙ (kaname#416). Позицию
        # несёт кейс набора платформы, и её прогоняет шаг конвейера там. Записью долга
        # она не является — у неё нет задачи, которая её прогонит, — а модулем этого
        # дерева не несётся. Запись о доме судится в обе стороны, как и долг: позиция
        # без уровня E, позиция, которую несёт свой модуль, и позиция с двумя исходами
        # сразу — находки; координата вне закрытой формы — тоже. Различие против
        # законного близнеца — в одном факте.
        (acc / "synthetic.md").write_text(base_heads, encoding="utf-8")
        hcase = "PRO-Robotech/kacho:gateway/tests/newman/cases/synthetic.py"
        hstep = "PRO-Robotech/kacho:.github/workflows/e2e-newman.yml «гейт — синтетика»"
        for label, debt, home, want_rc, want_texts in (
                ("ЗАКОННЫЙ БЛИЗНЕЦ: позиция E записана домом другого репозитория по форме — "
                 "молчание", {}, {"SYN-03": (hcase, hstep)}, 0, ()),
                ("запись дома позиции, которую несёт свой модуль, — пережила предмет",
                 {}, {"SYN-03": (hcase, hstep), "SYN-01": (hcase, hstep)}, 1,
                 ("позиции SYN-01", "несёт модуль carrier")),
                ("запись дома позиции без уровня E — без предмета",
                 {}, {"SYN-03": (hcase, hstep), "SYN-02": (hcase, hstep)}, 1,
                 ("позиции SYN-02", "нет ни в одной приёмке")),
                ("позиция записана и долгом, и домом — исход у позиции один",
                 {"SYN-03": ("довод", hold)}, {"SYN-03": (hcase, hstep)}, 1,
                 ("позиция SYN-03", "исход у позиции один")),
                ("кейс дома без приставки репозитория — находка",
                 {}, {"SYN-03": ("gateway/tests/newman/cases/synthetic.py", hstep)}, 1,
                 ("кейс дома позиции SYN-03", "вне закрытой формы")),
                ("кейс дома в ЭТОМ репозитории — находка: свой модуль судится модулем",
                 {}, {"SYN-03": ("PRO-Robotech/kaname:tests/newman/cases/synthetic.py", hstep)},
                 1, ("кейс дома позиции SYN-03", "вне закрытой формы")),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: дом — проба браузером платформы по форме — молчание",
                 {}, {"SYN-03": ("PRO-Robotech/kacho:ui-future/e2e/specs/synthetic.spec.ts",
                                 "PRO-Robotech/kacho:.github/workflows/console-e2e.yml «гейт — синтетика»")},
                 0, ()),
                ("проба браузером в ЭТОМ репозитории — находка: своя проба судится деревом",
                 {}, {"SYN-03": ("PRO-Robotech/kaname:ui/e2e/specs/synthetic.spec.ts", hstep)}, 1,
                 ("кейс дома позиции SYN-03", "вне закрытой формы")),
                ("файл браузерной семьи вне каталога проб — находка",
                 {}, {"SYN-03": ("PRO-Robotech/kacho:ui-future/e2e/synthetic.ts", hstep)}, 1,
                 ("кейс дома позиции SYN-03", "вне закрытой формы")),
                ("шаг дома без файла конвейера — находка",
                 {}, {"SYN-03": (hcase, "PRO-Robotech/kacho: «гейт — синтетика»")}, 1,
                 ("шаг дома позиции SYN-03", "вне закрытой формы")),
                ("шаг другого репозитория, чем кейс, — находка",
                 {}, {"SYN-03": (hcase, "PRO-Robotech/kaname:.github/workflows/e2e-newman.yml "
                                        "«гейт — синтетика»")}, 1,
                 ("позиции SYN-03", "в другом репозитории, чем её кейс"))):
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(pn, workflows=pwf_runs, ledger=pled, scenario_debt=debt,
                         scenario_home=home)
            _c(f"дом позиции: {label} (код {want_rc})",
               rc == want_rc and all(w in err.getvalue() for w in want_texts),
               f"код {rc}; {err.getvalue()[:500]}")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = run(pn, workflows=pwf_runs, ledger=pled, scenario_debt={},
                     scenario_home={"SYN-03": (hcase, hstep)})
        hout = buf.getvalue()
        _c("дом позиции: перепись числом — позиция не в долге, а в доме другого репозитория",
           rc == 0 and ("позиций 2 — гоняется 1 · собрана, коллекция не гоняется 0 · долг 0 · "
                        "в доме другого репозитория 1") in hout, f"код {rc}; {hout[-900:]}")
        _c("дом позиции: строка позиции называет кейс и шаг дома и говорит, что дом здесь "
           "не сверялся",
           f"SYN-03 [synthetic.md] — в доме PRO-Robotech/kacho: кейс {hcase}, шаг {hstep}" in hout
           and "сверка с деревом дома здесь НЕ выполняется" in hout, hout[-900:])

        # Ось 21: ДОВОД ОБ ОТСУТСТВИИ ОПРОВЕРЖИМ ДЕРЕВОМ (kaname#643). Двадцать семь
        # записей Ф13 несли довод «полосы входа ключом в дереве нет» после того,
        # как полосу посадили (`internal/handler/loginlanehttp/handler.go`), и
        # перепись зеленела: довод она читала как прозу. Утверждение об отсутствии
        # в дереве — утверждение о дереве, и судится оно предикатом по дереву.
        # Пара по каждой стороне, различие в одном факте против близнеца.
        root21 = pn.parents[1]
        (root21 / "internal").mkdir(parents=True, exist_ok=True)
        (root21 / "internal" / "lane.go").write_text("package lane\n", encoding="utf-8")
        claim = {"синтетика": (re.compile(r"синтетической полосы в дереве нет"),
                               re.compile(r"/syn/v1/lane"), ("internal",))}
        absent = ("синтетической полосы в дереве нет: путь `/syn/v1/lane` не называет ни один "
                  "файл продукта", hold)
        for label, write, debt, claims, want_rc, want_texts in (
                ("довод об отсутствии, а предмет в дереве есть — опровергнут, находка",
                 'const p = "/syn/v1/lane"\n', {"SYN-03": absent}, claim, 1,
                 ("позиции SYN-03", "опровергнут деревом", "internal/lane.go:2")),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: тот же довод, предмета в дереве нет — молчание",
                 "", {"SYN-03": absent}, claim, 0, ()),
                ("довод об отсутствии без предиката — находка: проза не судится",
                 "", {"SYN-03": absent}, {}, 1, ("позиции SYN-03", "предиката у него нет")),
                ("ЗАКОННЫЙ БЛИЗНЕЦ: довод без утверждения об отсутствии — молчание",
                 'const p = "/syn/v1/lane"\n', {"SYN-03": ("довод", hold)}, {}, 0, ()),
                ("каталога предиката нет — находка о слепоте, а не молчание",
                 "", {"SYN-03": absent},
                 {"синтетика": (claim["синтетика"][0], claim["синтетика"][1], ("nowhere",))}, 1,
                 ("осмотрено файлов 0",)),
                ("запись предиката, которую не называет ни один довод, — пережила довод",
                 "", {"SYN-03": ("довод", hold)}, claim, 1,
                 ("«синтетика»", "пережила свой довод"))):
            (root21 / "internal" / "lane.go").write_text("package lane\n" + write, encoding="utf-8")
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
                rc = run(pn, workflows=pwf_runs, ledger=pled, scenario_debt=debt,
                         absence_claims=claims)
            _c(f"довод об отсутствии: {label} (код {want_rc})",
               rc == want_rc and all(w in err.getvalue() for w in want_texts),
               f"код {rc}; {err.getvalue()[:500]}")
        (root21 / "internal" / "lane.go").write_text("package lane\n", encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = run(pn, workflows=pwf_runs, ledger=pled, scenario_debt={"SYN-03": absent},
                     absence_claims=claim)
        _c("довод об отсутствии: перепись осмотренного напечатана числом",
           rc == 0 and "доводы об отсутствии: прочитано 1 · с предикатом 1 · осмотрено файлов 1"
           in buf.getvalue(), f"код {rc}; {buf.getvalue()[-600:]}")

    # Ось 21, живое дерево: ИСТОРИЧЕСКИЙ ДОВОД Ф13 возвращается в ведомость и
    # обязан ей ронять перепись — на настоящем дереве, а не на синтетике. Обе
    # стороны предиката: зарегистрированный предикат даёт «опровергнут» с
    # координатой полосы; без регистрации довод отвергается как непроверяемый.
    # Сверка зовётся напрямую: позиция Ф13 записью долга в дереве больше не стоит,
    # и полная перепись покраснела бы ещё и «пережила предмет» — инъекция роняет
    # только своё.
    old_f13 = ("полосы входа ключом в дереве нет: путей `/iam/v1/auth/access-key/begin` и "
               "`/iam/v1/auth/access-key/login` и вида формы `access-key-login` не называет ни один "
               "файл продукта (`internal`, `cmd`, `proto`, `deploy` → 0) — слать кейсу некуда")
    f13_claim = {"полоса входа ключом": (re.compile(r"полосы входа ключом в дереве нет"),
                                         re.compile(r"access-key/(begin|login)|access-key-login"),
                                         ("internal", "cmd", "proto", "deploy"))}
    live, census = reconcile_absence_claims(ROOT, {"позиции Ф13-01": old_f13}, f13_claim)
    _c("живое дерево: исторический довод Ф13 опровергнут предикатом и назван координатой",
       len(live) == 1 and "опровергнут деревом" in live[0]
       and re.search(r"первое internal/\S+\.go:\d+", live[0]) is not None and census["files"] > 0,
       f"{live} {census}")
    live, _ = reconcile_absence_claims(ROOT, {"позиции Ф13-01": old_f13}, {})
    _c("живое дерево: тот же довод без предиката — отвергнут как непроверяемый",
       len(live) == 1 and "предиката у него нет" in live[0], f"{live}")
    live, census = reconcile_absence_claims(ROOT, {"позиции Ф13-01": "довод без отсутствия"}, f13_claim)
    _c("живое дерево: ЗАКОННЫЙ БЛИЗНЕЦ — довод без утверждения об отсутствии не судится",
       live == [] and census["claims"] == 0, f"{live} {census}")

    # Ось 22: ДЕРЖАТЕЛЬ ЖИВ (kaname#468). Запись долга держится задачей, которая её
    # снимет; закрытая задача ничего не снимет, и запись переживает держателя молча:
    # Ф5-24 держала закрытая kacho#1269, Ф5-12 — закрытая kaname#475. Трекер —
    # подставляемая обёртка, сеть в инъекции не нужна. Различие против близнеца —
    # в одном факте: состояние задачи держателя.
    syn_ledger = {"syn-col": ("C", "довод", "PRO-Robotech/kaname#9001 — снимет препятствие")}
    syn_debt = {"SYN-01": ("довод", "PRO-Robotech/kacho#9002 — заведёт кейс"),
                "SYN-02": ("довод", "PRO-Robotech/kacho#9002 — заведёт кейс")}
    for label, states, want_bad, want_unmet, want_texts in (
            ("ЗАКОННЫЙ БЛИЗНЕЦ: оба держателя открыты — молчание",
             {"PRO-Robotech/kaname#9001": "open", "PRO-Robotech/kacho#9002": "open"}, 0, 0, ()),
            ("держатель позиций закрыт — находка называет обе записи и держателя",
             {"PRO-Robotech/kaname#9001": "open", "PRO-Robotech/kacho#9002": "closed"}, 1, 0,
             ("PRO-Robotech/kacho#9002", "позиции SYN-01", "позиции SYN-02", "закрыт")),
            ("держатель коллекции закрыт — находка называет коллекцию",
             {"PRO-Robotech/kaname#9001": "closed", "PRO-Robotech/kacho#9002": "open"}, 1, 0,
             ("PRO-Robotech/kaname#9001", "коллекции syn-col")),
            ("трекер не ответил — не находка и не молчание, а «не выполнилось»",
             {"PRO-Robotech/kaname#9001": "open"}, 0, 1, ("PRO-Robotech/kacho#9002",))):
        bad, unmet, census = reconcile_holder_liveness(syn_ledger, syn_debt, states.get)
        text = "\n".join(bad + unmet)
        _c(f"живость держателя: {label}",
           len(bad) == want_bad and len(unmet) == want_unmet and all(w in text for w in want_texts)
           and census["holders"] == 2 and census["records"] == 3, f"{bad} {unmet} {census}")
    _, _, census = reconcile_holder_liveness({}, {}, lambda _ref: "open")
    _c("живость держателя: пустая ведомость — ноль держателей названо числом, а не молчанием",
       census == {"holders": 0, "records": 0, "open": 0, "closed": 0, "unknown": 0}, f"{census}")
    # Провязка в перепись — на объявленном дереве: держатель, которого трекер называет
    # закрытым, роняет перепись кодом 1 с именем записи; все открыты — код 0;
    # трекер молчит — код 75.
    declared_refs = sorted({m.group(1) for _w, h in SCENARIO_DEBT.values()
                            if (m := HOLDER_REF_RE.match(h or ""))})
    victim = declared_refs[0] if declared_refs else ""
    for label, tracker, want_rc, want_text in (
            ("ЗАКОННЫЙ БЛИЗНЕЦ: все держатели открыты — код 0", lambda _ref: "open", 0, ""),
            ("один держатель закрыт — код 1 и его имя",
             lambda ref: "closed" if ref == victim else "open", 1, victim),
            ("трекер молчит — код 75, а не зелёное", lambda _ref: None, RC_UNMET, "не выполнилось")):
        err = io.StringIO()
        with contextlib.redirect_stdout(err), contextlib.redirect_stderr(err):
            rc = run(ROOT / "tests" / "newman", tracker=tracker)
        _c(f"живость держателя в переписи дерева: {label}",
           bool(victim) and rc == want_rc and want_text in err.getvalue(), f"код {rc}; {err.getvalue()[-600:]}")
    print()
    if _F:
        print(f"САМОПРОВЕРКА ПРОВАЛЕНА: {len(_F)} — {', '.join(_F)}", file=sys.stderr)
        return 1
    print("ДОКАЗАНО: пустой обход отвергается, поверхность и препятствия выводятся из "
          "коллекции, а законный близнец (тот же адрес, но пустой ключ посева) уезжает "
          "в другую половину переписи.")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--newman", default=str(ROOT / "tests" / "newman"))
    ap.add_argument("--workflows", default=str(ROOT / ".github" / "workflows"))
    ap.add_argument("--self-test", action="store_true")
    args = ap.parse_args()
    if args.self_test:
        return self_test()
    return run(pathlib.Path(args.newman), pathlib.Path(args.workflows))


if __name__ == "__main__":
    sys.exit(main())
